void file_fread_chunks_callback(FILE* f,int bufsize,perline callback,void* p) {

	char* s = (char*)malloc(bufsize+1);

	int rsize = fread(s,1,bufsize,f);
	while (rsize == bufsize) {
		callback(s,rsize,p);
		rsize = fread(s,1,bufsize,f);
	}
	if (0 <= rsize && rsize < bufsize) {
		callback(s,rsize,p);
	}

	free(s);
}

