	Vector2(T x, T y) :x(x), y(y) {}
	template<typename U> Vector2(Vector2<U> v) : x((T)v.x), y((T)v.y) {}
	Vector2 operator+=(Vector2 it) { x += it.x; y += it.y; return *this; };
	Vector2 operator-=(Vector2 it) { x -= it.x; y -= it.y; return *this; };
	Vector2 operator*=(Vector2 it) { x *= it.x; y *= it.y; return *this; };
	Vector2 operator/=(Vector2 it) { x /= it.x; y /= it.y; return *this; };
	Vector2 operator+=(T it) { x += it; y += it; return *this; };
	Vector2 operator-=(T it) { x -= it; y -= it; return *this; };
	Vector2 operator*=(T it) { x *= it; y *= it; return *this; };
	Vector2 operator/=(T it) { x /= it; y /= it; return *this; };
	Vector2 operator-() { return { -x,-y }; }
