};
template<typename T>
struct Vector3 {
	Vector3() = default;
	Vector3(T v) :x(v), y(v), z(v) {}
	Vector3(T x, T y, T z) :x(x), y(y), z(z) {}
	template<typename U> Vector3(Vector3<U> v) : x((T)v.x), y((T)v.y), z((T)v.z) {}
	Vector3 operator+=(Vector3 it) { x += it.x; y += it.y; z += it.z; return *this; };
	Vector3 operator-=(Vector3 it) { x -= it.x; y -= it.y; z -= it.z; return *this; };
	Vector3 operator*=(Vector3 it) { x *= it.x; y *= it.y; z *= it.z; return *this; };
	Vector3 operator/=(Vector3 it) { x /= it.x; y /= it.y; z /= it.z; return *this; };
	Vector3 operator+=(T it) { x += it; y += it; z += it; return *this; };
	Vector3 operator-=(T it) { x -= it; y -= it; z -= it; return *this; };
	Vector3 operator*=(T it) { x *= it; y *= it; z *= it; return *this; };
	Vector3 operator/=(T it) { x /= it; y /= it; z /= it; return *this; };
	Vector3 operator-() { return { -x,-y,-z }; }
