struct mat3 { vec3 x, y, z; };
inline vec2 operator+(vec2 v0, vec2 v1) { return { v0.x + v1.x , v0.y + v1.y }; }
inline vec2 operator-(vec2 v0, vec2 v1) { return { v0.x - v1.x , v0.y - v1.y }; }
inline vec2 operator*(vec2 v0, vec2 v1) { return { v0.x * v1.x , v0.y * v1.y }; }
inline vec2 operator/(vec2 v0, vec2 v1) { return { v0.x / v1.x , v0.y / v1.y }; }
inline vec3 operator+(vec3 v0, vec3 v1) { return { v0.x + v1.x , v0.y + v1.y , v0.z + v1.z }; }
inline vec3 operator-(vec3 v0, vec3 v1) { return { v0.x - v1.x , v0.y - v1.y , v0.z - v1.z }; }
inline vec3 operator*(vec3 v0, vec3 v1) { return { v0.x * v1.x , v0.y * v1.y , v0.z * v1.z }; }
inline vec3 operator/(vec3 v0, vec3 v1) { return { v0.x / v1.x , v0.y / v1.y , v0.z / v1.z }; }
inline vec3 operator*(const mat3& transposed, vec3 v) { return v.x * transposed.x + v.y * transposed.y + v.z * transposed.z; }
inline float dot(vec3 v0, vec3 v1) { return v0.x * v1.x + v0.y * v1.y + v0.z * v1.z; }
inline vec3 cross(vec3 v0, vec3 v1) { return { v0.y * v1.z - v0.z * v1.y,v0.z * v1.x - v0.x * v1.z,v0.x * v1.y - v0.y * v1.x }; }
inline vec3 reflect(vec3 wi, vec3 n) { return  2.0f * dot(wi, n) * n - wi; }
inline float length_sq(vec3 v) { return v.x * v.x + v.y * v.y + v.z * v.z; }
inline float length(vec3 v) { return sqrt(length_sq(v)); }
inline vec3 normalize(vec3 v) { return v / length(v); }
inline vec3 abs(vec3 v) { return { abs(v.x),abs(v.y),abs(v.z) }; }
inline vec3 exp(vec3 v) { return { exp(v.x),exp(v.y),exp(v.z) }; }
inline float radians(float degrees) { return degrees * PI / 180.0f; }
inline float clamp(float x, float min_, float max_) { return std::max(std::min(x, max_), min_); }
inline vec3 clamp(vec3 v, vec3 min_, vec3 max_) { return { clamp(v.x,min_.x,max_.x),clamp(v.y,min_.y,max_.y) ,clamp(v.z,min_.z,max_.z) }; }
inline vec3 min(vec3 a, vec3 b) { return { std::min(a.x,b.x),std::min(a.y,b.y),std::min(a.z,b.z) }; }
inline vec3 max(vec3 a, vec3 b) { return { std::max(a.x,b.x),std::max(a.y,b.y),std::max(a.z,b.z) }; }

inline void coordinate_system(vec3 n, vec3& t, vec3& b) {
	if (abs(n.x) > abs(n.y)) t = vec3(-n.z, 0, n.x) / sqrt(n.x * n.x + n.z * n.z);
	else t = vec3(0, n.z, -n.y) / sqrt(n.y * n.y + n.z * n.z);
	b = cross(n, t);
}

inline vec2 concentric_sample_disk(vec2 u) {
	u = vec2(u.x * 2 - 1.0f, u.y * 2 - 1.0f);
	float theta, r;
	if (abs(u.x) > abs(u.y)) {
		r = u.x; theta = PI / 4.0f * u.y / u.x;
	}
	else {
		r = u.y; theta = PI / 2.0f - PI / 4.0f * (u.x / u.y);
	}
	return r * vec2(cos(theta), sin(theta));
}

inline vec3 cosine_weighted_sample(vec2 u, vec3 n) {
	vec2 d = concentric_sample_disk(u);
	mat3 local_to_world = { 0,0,n };
	coordinate_system(n, local_to_world.x, local_to_world.y);
	return local_to_world * vec3(d.x, d.y, sqrt(1.0f - d.x * d.x - d.y * d.y));
}

template<typename F> void parallel_for(int n, F f) {
	static std::atomic<int> task_counter = 0;
	static std::vector<std::thread> threads(std::thread::hardware_concurrency() - 1);
	task_counter = 0;
	for (size_t i = 0; i < threads.size(); i++)threads[i] = std::thread([n, f, i]() {
		int offset = task_counter.fetch_add(1);
		while (offset < n) {
			f(offset); offset = task_counter.fetch_add(1);
		}
		});
	for (auto& t : threads)t.join();
}

inline uint64_t mix_bits(uint64_t v) {
	v ^= (v >> 31);
	v *= 0x7fb5d329728ea185;
	v ^= (v >> 27);
	v *= 0x81dadef4bc2dd44d;
	v ^= (v >> 33);
	return v;
}

template<typename T, typename... Args>
void hash_recursive_copy(char* buf, T v, Args... args) {
	*(T*)buf = v;
	if constexpr (sizeof...(Args) != 0)
		hash_recursive_copy(buf + sizeof(T), args...);
}

template <typename T>
inline uint64_t murmur_hash(const T* key, size_t len) {
	const uint64_t m = 0xc6a4a7935bd1e995ull;
	const int r = 47;
	uint64_t h = len * m;
	const uint64_t* data = (const uint64_t*)key;
	const uint64_t* end = data + (len / 8);
	while (data != end) {
		uint64_t k;
		if constexpr (alignof(T) >= 8 || ((uintptr_t)key & 7) == 0) k = *data++;
		else k = *(data++);
		k = ((k * m) >> r) * m;
		h = (h ^ k) * m;
	}
	size_t i = (len & 7) - 1;
	h ^= uint64_t(data[i]) << (i * 8);
	if (i == 0)h *= m;
	h ^= ((h ^ (h >> r)) * m) >> r;
	return h;
}

template <typename ... Args>
struct count_bytes;
template <>
struct count_bytes<> {
	constexpr static size_t value = 0u;
};
template <typename T, typename... Args>
struct count_bytes<T, Args...> {
	constexpr static size_t value = sizeof(T) + count_bytes<Args...>::value;
};

template<typename... Args>
inline uint64_t hash(Args... args) {
	constexpr size_t sz = count_bytes<Args...>::value;
	constexpr size_t n = (sz + 7) / 8;
	uint64_t buf[n];
	hash_recursive_copy((char*)buf, args...);
	return murmur_hash(buf, sz);
}

class RNG {
public:
	RNG() :state(0x853c49e6748fea9bULL), inc(0xda3e39cb96b95bdbULL) {};
	RNG(uint64_t seq) {
		state = 0u;
		inc = (seq << 1u) | 1u;
		uniform32u();
		state += mix_bits(seq);
		uniform32u();
	};

	uint32_t uniform32u() {
		uint64_t oldstate = state;
		state = oldstate * 0x5851f42d4c957f2dULL + inc;
		uint32_t xorshifted = (uint32_t)(((oldstate >> 18u) ^ oldstate) >> 27u);
		uint32_t rot = (uint32_t)(oldstate >> 59u);
		return (xorshifted >> rot) | (xorshifted << ((~rot + 1u) & 31));
	}
	float uniformf() {
		return std::min<float>(0x1.fffffep1f, uniform32u() * 0x1p-32f);
	}
	vec2 uniform2f() {
		return { uniformf(),uniformf() };
	}
private:
	uint64_t state, inc;
};

