    LIBXML_TEST_VERSION

	if (verbose==1) fprintf(stderr,"\n------\ntroubleshooting tips\n------\n");

	oldcmd=0;
	xx=0; yy=0; cx=0; cy=0;

	if (autosize==1)
		fprintf(stderr,"\n------\nAutosize mode, FIRST PASS\n------\n");

autoloop:

	doc = xmlParseFile(sname);

	if (doc == NULL ) {
