				chkstyle (node);

				x1=y1=x2=y2=0;
				oldx=oldy=0;
				svcx=svcy=0;

				cmd='[';

				attr = xmlGetProp(node, (const xmlChar *) "points");
				if(attr != NULL) {
					sprintf(Dummy,"%s",(const char *)attr);
					//xmlFree(attr);

/*
					cx=x1; cy=y1;
					scale_and_shift();
					move_to (x,y);
					oldx=x; oldy=y;
					line_to (x,y,oldx,oldy);

