				else {
					sprintf(Dummy,"%s",(const char *)attr);
					//xmlFree(attr);
				}
				if (verbose==1) fprintf(stderr,"\n  Processing path group #%u, id: %s",pathcnt,Dummy);

				chkstyle(node);

				attr = xmlGetProp(node, (const xmlChar *) "d");

				nodecnt=0; skipcnt=0;
				fprintf(dest,"\n\n\t// Group #%u - %s\n", pathcnt,Dummy);

				// Init rel margin limits (inverted)
				lm = width;
				rm = 0;
				tm = height;
				bm = 0;

				elementcnt = 0;

				if(attr != NULL) {

					/* ************************* */
					/* MAIN PATH CONVERSION LOOP */
					/* ************************* */
					//spath=strdup((char *)attr);
					sprintf (spath,"%s",(const char *)attr);
					path=spath;
					curves_cnt=0;
					oldx=oldy=0;
					svcx=svcy=0;

					while (strlen(path)>0) {
						path=skip_spc(path);
						cmd=*path;
						if ((isdigit(cmd))||(cmd=='-'))
							switch (oldcmd) {
								case 'm':
									cmd = 'l';
									break;
								case 'M':
									cmd = 'L';
									break;
								default:
									cmd=oldcmd;
							}
						else {
							curves_cnt=0;
							oldcmd=cmd;
							path++;
							skip_spc(path);
						}
/*
		  The <path> Tag - The following commands are available for path data:

			* M = moveto
			* L = lineto
			* H = horizontal lineto
			* V = vertical lineto
			* C = curveto
			* S = smooth curveto
			* Q = quadratic Belzier curve
			* T = smooth quadratic Belzier curveto
			* A = elliptical Arc
			* Z = closepath
*/
						if ((cmd == 'Z')||(cmd == 'z')) {
							if ((x != inix) || (y != iniy))
