								path++;
								skip_spc(path);
							}
						} else {
							nodecnt++;
							/* skip 5 parameters if cmd is 'arc'*/
							if ((cmd == 'A')||(cmd == 'a')) {
								path=skip_num(path);
								path=skip_num(path);
								path=skip_num(path);
								path=skip_num(path);
								path=skip_num(path);
							}
							/* Vertical and Horizontal lines take 1 parameter only */
							if (toupper(cmd) != 'V') {
								cx=atof(path)-xx;
								path=skip_num(path);
							}
							if (toupper(cmd) != 'H') {
								cy=atof(path)-yy;
								path=skip_num(path);
							}
							////fprintf(stderr,"\n%s",path);
							/* don't consider the second parameter of a relative curve*/
							if ((cmd == 'c')||(cmd == 'q')||(cmd == 't')) {
								curves_cnt++;
								if ((curves_cnt % 3)==1) {
									path=skip_num(path);
									path=skip_num(path);
									curves_cnt++;
									}
							} else curves_cnt=0;
							/* Lower case commands take relative coordinates */
							if (toupper(cmd)!=cmd) {
								if (cmd != 'v') cx=cx+svcx;
								if (cmd != 'h') cy=cy+svcy;
								cmd=toupper(cmd);
							}
							svcx=cx; svcy=cy;

