										}
									} else {
										if (elementcnt>maxelements) {
											fprintf(dest,"\n\t");
											elementcnt=0;
										}
									}
									break;
							}
							oldx=x; oldy=y;
						}

						path=skip_spc(path);
					}

					close_area();

					if (pathdetails>0) printf("\n");

					inipath=0;
				}
				//xmlFree(attr);
				//free(spath);
				if (verbose==1) fprintf(stderr,"\n    Extracted %u nodes, (%u overlapping coordinates skipped)\n\n",nodecnt-skipcnt, skipcnt);

				/* keep track of absolute margins */
				if (alm>lm) alm=lm;
				if (arm<rm) arm=rm;
				if (atm>tm) atm=tm;
				if (abm<bm) abm=bm;

