void mqtt_utils_logger_init() { logger_id = logger_helper_enable(MQTT_UTILS_LOGGER, LOGGER_DEBUG, true); }

int mqtt_utils_logger_release() {
  logger_helper_release(logger_id);
  if (logger_helper_destroy() != RC_OK) {
