size_t cz_strspn(const char *string, const char *control)
{
	const unsigned char *str = (const unsigned char*)string;
	const unsigned char *ctrl = (const unsigned char*)control;
	unsigned char map[32];
	int count;
	cz_memset(map, 0, 32);
	while (*ctrl) {
		map[*ctrl >> 3] |= (1 << (*ctrl & 7));
		ctrl++;
	}
	if (*str) {
		count = 0;
		while (map[*str >> 3] & (1 << (*str & 7))) {
			count++;
			str++;
		}
		return count;
	}
	return 0;
}

size_t cz_strcspn(const char *string, const char *control)
{
	const unsigned char *str = (const unsigned char*)string;
	const unsigned char *ctrl = (const unsigned char*)control;
	unsigned char map[32];
	int count;
	cz_memset(map, 0, 32);
	while (*ctrl) {
		map[*ctrl >> 3] |= (1 << (*ctrl & 7));
		ctrl++;
	}
	count = 0;
	map[0] |= 1;
	while (!(map[*str >> 3] & (1 << (*str & 7)))) {
		count++;
		str++;
	}
	return count;
}

char* cz_strpbrk(const char *string, const char *control)
{
	const unsigned char *str = (const unsigned char*)string;
	const unsigned char *ctrl = (const unsigned char*)control;
	unsigned char map[32];
	cz_memset(map, 0, 32);
	while (*ctrl) {
		map[*ctrl >> 3] |= (1 << (*ctrl & 7));
		ctrl++;
	}
	for (; *str; str++) {
		if (map[*str >> 3] & (1 << (*str & 7)))
			return (char*)str;
	}
	return NULL;
}


char* cz_strrev(char *string)
{
	char *start = string;
	char *left = string;
	char ch;
	if (string[0]) {
		for (; string[1]; string++);
		for (; left < string; ) {
			ch = *left; *left++ = *string; *string-- = ch;
		}
	}
	return start;	
}


