void u8_cmov(uint8_t *r, uint8_t a, uint8_t bit){
    uint8_t b = bit & 0x01;
    uint8_t mask = (uint8_t) (-(int8_t) b);
    uint8_t h,x;
    h = *r;
    x = h ^ a;
    x &= mask;
    *r = *r ^ x;
}

void jubjub_field_frombytes(jubjub_fq r, const uint8_t *s){
    MEMZERO(r, sizeof(jubjub_fq));
