	    "\t-r\trepeat playlist\n"
	    "\r-s\tshuffle playlist\n"
	    "\t-c\tuse curses interface\n"
	    "\t-h\tdisplay this help message\n");
	exit(EXIT_FAILURE);
}

void
version(void)
{
	fprintf(stderr, "replay - version 0.2 alpha\n");
	fprintf(stderr, "Copyright 2008, <NAME>\n");

	exit(EXIT_SUCCESS);
}

