		    c3 = c2 - c3;
		    t2 = d2 - d3;
		    d3 = d2 + d3;
		    X[a2-1] = -X[b0-1] - d3;
		    X[b2-1] = -X[b1-1] + c3;
		    X[a3-1] = X[b1-1] + c3;
		    X[b3-1] = X[b0-1] - d3;
		    X[b1-1] = X[a1-1] + t2;
		    X[b0-1] = X[a0-1] - t1;
		    X[a0-1] += t1;
		    X[a1-1] -= t2;
		    rfft_adds += 12;
		}
	    }
	}
    }

    /*
     * For some reason the Imag part is coming out with the wrong
     * sign, so we reverse it here!  We need to figure this out!
     */
    for ( i = N/2+1; i < N; i++ )
	X[i] = -X[i];
}

