#define REDUCE(val, tbl) \
    do { \
        int32_t i; \
        for (i = 1; i < sizeof(tbl)/sizeof(tbl[0]); i++) { \
            if (val <= tbl[i]) { \
                val = tbl[i-1]; \
                break; \
            } \
        } \
    } while (0)

#define INCREASE(val, tbl) \
