	pkt_header = (struct ether_header *) data.buf;
        print_ether_addr( (char *) &pkt_header->ether_shost );
    	printf( "\n" );

/*  remainder of the RARP packet conforms to a struct ether_arp
    see <netinet/if_ether.h> and <netinet/arp.h>		*/

