int fcompare(FILE *fp1,FILE *fp2)
{	CStr(buf1,1024);
	CStr(buf2,1024);
	int off1,off2;
	int rc1,rc2,ri;
	int diff;

	off1 = ftell(fp1);
	off2 = ftell(fp2);
	diff = 0;
	for(;;){
		rc1 = fread(buf1,1,sizeof(buf1),fp1);
		rc2 = fread(buf2,1,sizeof(buf2),fp2);
		if( rc1 != rc2 ){
			diff = 1;
			break;
