static void normpath(PCStr(src),PVStr(dst))
{	refQStr(dp,dst); /**/
	const char *sp;
	int ch;

	for( sp = src; ; sp++ ){
		ch = *sp;
		setVStrPtrInc(dp,ch);
		if( ch == 0 )
			break;
		assertVStr(dst,dp+1);
		if( *sp == '/' && sp[1] == '/' )
			sp++;
	}
	setVStrPtrInc(dp,0);
}

