static int beshared(PCStr(path),int isdir)
{	int match;
	CStr(xpath,1024);

	if( shared_frex == 0 )
		return 0;

	normpath(path,AVStr(xpath));
	if( isdir && strtailchr(xpath) != '/' )
		strcat(xpath,"/");

