FileSize copyfile2(FILE *sfp,FILE *dfp,int doflush)
{	CStr(buff,8*1024);
	FileSize totalc;
	int rcc;
	int wcc;

	totalc = 0;
	for(;;){
		rcc = fread(buff,1,sizeof(buff),sfp);
		if( rcc == 0 )
			break;
		totalc += rcc;
		/*
		if( fwrite(buff,1,rcc,dfp) == 0 )
		*/
		wcc = fwrite(buff,1,rcc,dfp);
		if( wcc <= 0 )
			break;
		if( ferror(dfp) ){
			syslog_ERROR("copyfile() detected ferror()\n");
			break;
		}
	}
	if( doflush )
		fflush(dfp);
	return totalc;
}

