void path_escchar(xPVStr(path))
{	char sc;
	const char *sp;
	refQStr(dp,path); /**/
	const char *buff;

	if( !ColonForDrive() )
		return;

	if( isalpha(path[0]) && path[1] == ':' )
		path += 2;

	/*
	 * escape "//", "\\", and one of ':*?"<>|' on Windows
	 */
	if( strpbrk(path,":") == NULL && strstr(path+2,"./") == NULL )
	if( strstr(path,"//") == 0 )
	if( strstr(path,"\\\\") == 0 )
	if( strpbrk(path,":*?\"<>|") == 0 )
		return;

	buff = stralloc(path);
	dp = path;
	for( sp = buff; sc = *sp; sp++ ){
		assertVStr(path,dp+3);
		if( sc == '.' && sp[1] == '/' ){
			setVStrPtrInc(dp,'%');
			setVStrPtrInc(dp,'2');
			setVStrPtrInc(dp,'E');
		}else
		if( sc == ':' ){
			if( sp[1] == '/' ){
				setVStrPtrInc(dp,'%');
				setVStrPtrInc(dp,'3');
				setVStrPtrInc(dp,'A');
			}else{
				setVStrPtrInc(dp,'.');
				setVStrPtrInc(dp,'.');
			}
		}else
		if( isWindows() && sc == '/' && sp[1] == '/' ){
			setVStrPtrInc(dp,'%');
			setVStrPtrInc(dp,'2');
			setVStrPtrInc(dp,'F');
		}else
		if( isWindows() && sc == '?' ){
			setVStrPtrInc(dp,'%');
			setVStrPtrInc(dp,'3');
			setVStrPtrInc(dp,'F');
		}else
		if( isWindows() && sc == '|' ){
			setVStrPtrInc(dp,'%');
			setVStrPtrInc(dp,'7');
			setVStrPtrInc(dp,'C');
		}else	setVStrPtrInc(dp,sc);
	}
	setVStrEnd(dp,0);
	free((char*)buff);
}

