int Fputs(PCStr(str),FILE *fp)
{	const char *dp;
	int rcode;
	int len,rcc;

	/* signal(SIGPIPE,... */

	if( (dp = strtailstr(str,"\r\n")) || (dp = strtailstr(str,"\n")) )
		len = dp - str;
	else	len = strlen(str);

	rcc = fwrite(str,1,len,fp);
