void chdir_cwd(PVStr(cwd),PCStr(go),int userdir)
{	refQStr(tp,cwd); /**/
	const char *cp;
	int uplen,len;

	for( cpyQStr(tp,cwd); *tp; tp++ ){}
	if( len = isFullpath(go) ){
		tp = (char*)cwd;
		while( 0 < len-- ){
			assertVStr(cwd,tp+1);
			setVStrPtrInc(tp,*go++);
