	}else
	if( userdir && go[0] == '~' ){
		if( go[1] == 0   ){ tp = (char*)cwd; go += 1; }else
		if( IsSep(go[1]) ){ tp = (char*)cwd; go += 2; }
	}

	while( *go ){
		uplen = 0;
		if( go[0] == '.' ){
			if( go[1] == 0   ){ go += 1; break; }
			if( IsSep(go[1]) ){ go += 2; continue; }
			if( go[1] == '.' ){
				if( go[2] == 0   ){ uplen = 2; } else
				if( IsSep(go[2]) ){ uplen = 3; }
			}
		}
		if( uplen ){
			if( cwd < tp ){
				while( cwd+1 < tp ){
					if( IsSep(tp[-1]) )
						tp--;
					else	break;
				}
				setVStrEnd(tp,0);
				if( cp = FindRDirSep(cwd) ){
					if( cp == cwd  )
						tp = (char*)cp + 1;
					else	tp = (char*)cp;
				}else	tp = (char*)cwd;
			}
			go += uplen;
		}else{
			if( cp = FindDirSep(go) )
				len = (cp - go) + 1;
			else	len = strlen(go);

			if( cwd < tp && !IsSep(tp[-1]) ){
				setVStrPtrInc(tp,'/');
			}
			strncpy(tp,go,len);
			tp += len;
			go += len;
		}
	}
	while( cwd+1 < tp ){
		if( IsSep(tp[-1]) )
			tp--;
		else	break;
	}
	setVStrEnd(tp,0);
}

