        printf("CONNECTED TO DB |%s| |%s| |%s|\n", DB_NAME, sname, dbt2_drizzle_port);
        db_init(sname, "", dbt2_drizzle_port);
#endif /* LIBDRIZZLE */
#ifdef LIBSQLITE
	db_init(sname);
#endif /* LIBSQLITE */

	if (!exiting && connect_to_db(&dbc) != OK) {
		LOG_ERROR_MESSAGE("db_connect() error, terminating program");
		printf("cannot connect to database, exiting...\n");
		exit(1);
	}
#else
