  sr.x = image->width * (frame % num_frames_x) + rect_x1;
  sr.y = image->height * (frame / num_frames_x) + rect_y1;
  sr.w = rect_width;
  sr.h = rect_height;

  dr.x = (BB_ORIGIN_X + x) / BB_SCALE_X - image->handle_x;
