void klee_enumerate_single_inputs() {
	int i=0, input_index=0;
	unsigned int do_quit=1;

	do_quit ^= 1;
	if (do_quit) {
		inputs[input_index++] = KLEE_QUITKEY;
		inputs[input_index++] = 0xDEADBEEF;
		return;
	}

	if (input_generation_type == 1) {
		if (!(input_data[0].c) && !(input_data[1].c) && !(input_data[2].c) && 
				!(input_data[3].c) && !(input_data[4].c) && !(input_data[5].c) && 
				!(input_data[6].c)) {
			inputs[0] = ('0'|0x80);
			inputs[1] = 0xDEADBEEF;
			inputs[2] = 0xDEADBEEF;
			return;
		}
	}

	input_data_t *cdata = &(input_data[current_piece]);

	for (i=cdata->rot; i>0; i--) {
		inputs[input_index++] = KLEE_UP;
	}

	for (i=cdata->s; i>0; i--) {
		inputs[input_index++] = cdata->s_type ? KLEE_RIGHT : KLEE_LEFT;
	}

	inputs[input_index++] = ' ';
	inputs[input_index++] = KLEE_QUITKEY;
	inputs[input_index++] = 0xDEADBEEF;

	cdata->s++;

	if (cdata->s > cdata->max_mov[cdata->s_type][cdata->rot]) {
		if (cdata->s_type == 1) {
			cdata->rot++;
		} 
		cdata->s_type ^= 1;
		cdata->s = 0;
		if (cdata->s_type == 1) {
			cdata->s++;
		}
	}

	if (cdata->rot >= cdata->max_rot) {
		//advance next piece 
		if (input_generation_type == 2) {
			if (current_enumerate_piece >= 6) {
				inputs[0] = ('0'|0x80);
				inputs[1] = 0xDEADBEEF;
			}
			current_enumerate_piece = (current_enumerate_piece + 1 ) % 7;
		} else if (input_generation_type == 1) {
			cdata->c = 0;
		}
		// reset piece data
		cdata->s = cdata->s_type = cdata->rot = 0;
	}
}

void klee_random_inputs_table() {
	unsigned int i=0, input_index=0;
	unsigned int rotations, do_quit, shifts, shift_type, do_invalid;

	MAKE_SYMBOLIC(&do_quit, "do_quit", 0);
	MAKE_SYMBOLIC(&do_invalid, "do_invalid", 1);
	MAKE_SYMBOLIC(&shifts,  "shifts", 5);
	MAKE_SYMBOLIC(&shift_type, "shift_type", 1);
	MAKE_SYMBOLIC(&rotations,"rotations", 2);

	input_data_t *cdata = &(input_data[current_piece]);

	if (do_quit) { 

		inputs[input_index++] = KLEE_QUITKEY;
	} else {
		KLEE_MOD(shift_type, 1);
		KLEE_MOD(rotations, cdata->max_rot-1);

		for (i=rotations; i>0; i--) {
			inputs[input_index++] = KLEE_UP;
		}

		unsigned int max_shift = cdata->max_mov[shift_type][rotations];

		//// If we are shifting left, don't ever have a shift distance of 0
		//if (shift_type) {
		//	max_shift--;
		//	inputs[input_index++] = KLEE_RIGHT;
		//}

		//char buf[64];
		//sprintf(buf, "Max Shift: %d", max_shift);
		//KPRINTF(buf);

		KLEE_MOD(shifts, max_shift);

		for (i=shifts; i>0; i--) {
			inputs[input_index++] = shift_type ? KLEE_RIGHT : KLEE_LEFT;
		}

		inputs[input_index++] = KLEE_DOWN;
		inputs[input_index++] = ' ';
	}

	inputs[input_index++] = 0xDEADBEEF;
}

void klee_random_inputs() {
	unsigned int i=0, rotations, do_quit, shifts, shift_type,do_invalid;

	MAKE_SYMBOLIC(&do_quit, "do_quit", 0);
	MAKE_SYMBOLIC(&do_invalid, "do_invalid", 1);
	MAKE_SYMBOLIC(&shifts,  "shifts", 5);
	MAKE_SYMBOLIC(&shift_type, "shift_type", 1);
	MAKE_SYMBOLIC(&rotations,"rotations", 2);

#ifndef KLEE
	static unsigned quit_round = 0;
	quit_round++;
	if (quit_round % 2 == 0)
		do_quit = 1;
	else
		do_quit = 0;

	if (input_generation_type != 0 && do_quit == 0) {
		inputs[i++] = KLEE_QUITKEY;
	} else {

#else

	if (do_quit == 0) {
		inputs[i++] = K_F10;
	}	else if (do_quit == 1) {
		inputs[i++] = KLEE_QUITKEY;
	} else {

#endif

		KLEE_MOD(shift_type, 1);
		if (shift_type == 0)
			shift_type = KLEE_LEFT;
		else
			shift_type = KLEE_RIGHT;

		//    Piece Types: 
		//    0    1    2    3    4    5    6
		//    ##X# .... .... .... .... .... ....
		//    .... .X#. #X#. #X#. #X.. .X#. #X#.
		//    .... .##. ..#. #... .##. ##.. .#..
		//    .... .... .... .... .... .... ....
		//    Rotational Positions:
		//    2    1    4    4    2    2    4
		//   
		//    Max Moves Left in each Rotation
		// 1  4    6    5    5    5    5    5   
		// 2  6    .    5    5    5    5    5  
		// 3  .    .    5    5    .    .    5  
		// 4  .    .    6    6    .    .    6    
		//
		//    Max Moves Right in each Rotation
		// 1  4    4    4    4    4    4    4    
		// 2  5    .    5    5    5    5    5   
		// 3  .    .    4    4    .    .    4   
		// 4  .    .    4    4    .    .    4     

		if (current_piece == 0) {
			KLEE_MOD(rotations, 1);
			if (shift_type == KLEE_LEFT) {
				if (rotations == 0) {
					KLEE_MOD(shifts, 4);
				} else {
					KLEE_MOD(shifts, 6);
				}
			} else {
				if (rotations == 0) {
					KLEE_MOD(shifts, 4);
				} else {
					KLEE_MOD(shifts, 5);
				}
			}
		}

		if (current_piece == 1) {
			rotations = 0;
			if (shift_type == KLEE_LEFT) {
				KLEE_MOD(shifts, 6);
			} else {
				KLEE_MOD(shifts, 4);
			}
		}

		if (current_piece == 2 || current_piece == 3 || current_piece == 6) {
			KLEE_MOD(rotations, 3);
			if (shift_type == KLEE_LEFT) {
				if (rotations == 3) {
					KLEE_MOD(shifts, 6);
			  } else {
					KLEE_MOD(shifts, 5);
				}
			} else {
				if (rotations == 1) {
					KLEE_MOD(shifts, 5);
				} else {
					KLEE_MOD(shifts, 4);
				}
			}
		}

		if (current_piece == 4 || current_piece == 5) {
			KLEE_MOD(rotations, 1);
			if (shift_type == KLEE_LEFT) {
				KLEE_MOD(shifts, 5);
			} else {
				if (rotations == 0) {
					KLEE_MOD(shifts, 4);
				} else {
					KLEE_MOD(shifts, 5);
				}
			}
		}

		switch (rotations) {
			case 3:
				inputs[i++] = KLEE_UP;
			case 2:
				inputs[i++] = KLEE_UP;
			case 1:
				inputs[i++] = KLEE_UP;
			default:
				break;
		}

		switch (shifts) {
			case 6:
				inputs[i++] = shift_type;
			case 5:
				inputs[i++] = shift_type;
			case 4:
				inputs[i++] = shift_type;
			case 3:
				inputs[i++] = shift_type;
			case 2:
				inputs[i++] = shift_type;
			case 1:
				inputs[i++] = shift_type;
			default:
				break;
		}

		//if (do_invalid)
		//	inputs[i++] = K_INVALID;

		//inputs[input_index++] = KLEE_DOWN;
		inputs[i++] = ' ';
	}
	inputs[i++] = 0xDEADBEEF;
	//print_inputs();
}

void klee_create_inputs() {

	// initialize game board with random tiles
	if (starting_height > 0) {
		Field *f = &fields[my_playernum-1];
		int x,y;
		for (y=0; y<=starting_height; y++) {
			for (x=0; x<FIELD_WIDTH; ++x) (*f)[FIELD_HEIGHT-y][x] = 1;
			(*f)[FIELD_HEIGHT-y][y % FIELD_WIDTH] = 0;
		}
	}

	switch (input_generation_type) {
#ifndef KLEE
		case 1:
		case 2:
			klee_enumerate_single_inputs();
			return;
#endif
		case 0:
		default:
			klee_random_inputs();
			return;
	}
}

int klee_getch() {
	int retval;
	if (input_generation_type >= 3) {
		int input, sinput;
		MAKE_SYMBOLIC(&sinput, "input", 0);
		// Using switch statement to decouple symbolic variable
		switch(sinput) {
		case KLEE_UP: 		{CLIVER_PRINT("KLEE_UP");      input = KLEE_UP;         } break;
		case KLEE_LEFT: 	{CLIVER_PRINT("KLEE_LEFT");    input = KLEE_LEFT;	} break;
		case KLEE_RIGHT: 	{CLIVER_PRINT("KLEE_RIGHT");   input = KLEE_RIGHT;	} break;
		case KLEE_QUITKEY:      {CLIVER_PRINT("KLEE_QUITKEY"); input = KLEE_QUITKEY;	} break;
		//case KLEE_EXITKEY:      {CLIVER_PRINT("KLEE_EXITKEY"); input = KLEE_EXITKEY;	} break;
		default: 		{CLIVER_PRINT("0xDEADBEEF");   input = 0xDEADBEEF;	} break;
		}
		if (input == 0xDEADBEEF) {
			g_last_round = g_round;
			g_new_piece = 0;
			retval = 0;
		} else {
			retval = input;
		}

	} else {
		if (input_index == 0) {
			klee_create_inputs();
		}

		if (inputs[input_index] == 0xDEADBEEF) {
			KPRINTF("last user input event");
			g_last_round = g_round;
			g_new_piece = 0;
			input_index = 0;
			memset(inputs, 0, INPUTS_LENGTH * sizeof(unsigned int));
			retval = 0;
		} else {
			retval = inputs[input_index++];
		}
	}

	return retval;
}

