vm_state_t *vm_main_run(const vm_char_t *src, size_t argc,
                        const vm_char_t **argv) {
  FILE *file = fopen(src, "rb");
  if (file == NULL) {
    for (const vm_char_t *i = VM_CAN_NOT_OPEN; *i != '\0'; i++) {
      vm_putchar(*i);
    }
    return NULL;
  }
  uint8_t nver = 0;
  fread(&nver, 1, 1, file);
  if (nver == 0) {
    vm_save_t save;
    vm_save_init(&save);
    while (true) {
      uint8_t byte = 0;
      size_t size = fread(&byte, 1, 1, file);
      if (size == 0) {
        break;
      }
      vm_save_byte(&save, byte);
    }
    vm_save_rewind(&save);
    vm_state_t *state = vm_run_save(save, argc, argv);
    vm_save_deinit(&save);
    return state;
  } else {
    size_t nops = 0;
    vm_opcode_t *vm_ops = vm_malloc(sizeof(vm_opcode_t) * VM_OPS_UNITS);
    if (nver <= 2) {
      vm_opcode_t *ops = &vm_ops[0];
      while (true) {
        uint16_t op = 0;
        size_t size = fread(&op, nver, 1, file);
        if (size == 0) {
          break;
        }
        nops += 1;
        *(ops++) = op;
      }
    } else if (nver <= 4) {
      vm_opcode_t *ops = &vm_ops[0];
      while (true) {
        uint32_t op = 0;
        size_t size = fread(&op, nver, 1, file);
        if (size == 0) {
          break;
        }
        nops += 1;
        *(ops++) = op;
      }
    } else if (nver <= 8) {
      vm_opcode_t *ops = &vm_ops[0];
      while (true) {
        uint64_t op = 0;
        size_t size = fread(&op, nver, 1, file);
        if (size == 0) {
          break;
        }
        nops += 1;
        *(ops++) = op;
      }
    }
    fclose(file);
    vm_state_t *state = vm_state_new(argc, (const char **)argv);
    vm_state_set_ops(state, nops, vm_ops);
    return vm_run(state);
  }
}

