    fprintf(stderr, "cannot read player 2 position\n");
    exit(EXIT_FAILURE);
  }
  pos1 = read_position(buf) - 1;
  w = solve(pos0, pos1);
  printf("%ld\n", w);
  return EXIT_SUCCESS;
}

