	for (i=0; i<3; i++) {
		K[i] = (double*)malloc( sz );
	}

	// Task loop
	do{
		// Update pointers
		pthread_mutex_lock( &mutex );
		start = sq;
		sq = start + task_size;	
		if (sq>=ld) {
			sq = ld;
			lock = 0x00;
		}
		end = sq;
		pthread_mutex_unlock( &mutex );		

		// Prepare data for every coordinate
		j = 0;
		for (k=start; k<end; k++) {
			i = M[k];			
			lv = I[i];
			K[0][j] = fabs( Vx[i] * INTER_FACTOR );
