    printf("Received response\n");
    printf("-------------------------------------------\n");
    while((n = read(res, buffer, sizeof(buffer)))>0)
    {
        buffer[n]= '\0' ; 
        printf("%s", buffer);
    }
    printf("-------------------------------------------\n");

    close(req);
    close(res);
    return 0;
}

