#ifdef VISUAL

static char *cl, *cm;
static int rows, cols;
static int tsave;
static struct termios saved_termios;
static struct termios tw;

void ttyfix(void)
{
  ioctl(0, TCSETS, &saved_termios);
}

void handler(int sig)
{
  if (tsave)
    ttyfix();
  kill(getpid(), sig);
  _exit(1);
}

static void visual_init(void)
{
  int p[2];
  int s;
  pid_t pid;
  struct winsize w;

  if (ioctl(0, TIOCGWINSZ, &w)) {
    perror("tiocgwinsz");
    exit(1);
  }
  rows = w.ws_row;
  cols = w.ws_col;

  if (pipe(p)) {
    perror("pipe");
    exit(1);
  }
  pid = fork();
  switch(pid) {
    case -1:
      perror("fork");
      exit(1);
    case 0:
      close(p[0]);
      dup2(p[1],0);
      dup2(0,1);
      execl("/usr/lib/tchelp", "tchelp", "cl$cm$", NULL);
      perror("exec");
      _exit(1);
  }
  close(p[1]);
  wait(NULL);
  if (read(p[0], &s, sizeof(int)) != sizeof(int)) {
    perror("tchelp");
    exit(1);
  }
  cl = sbrk((s + 3) & ~3);
  if (cl == (void *)-1) {
    perror("sbrk");
    exit(1);
  }
  if (read(p[0], cl, s) != s) {
    perror("tchelp");
    exit(1);
  }
  close(p[0]);
  cm = cl + strlen(cl) + 1;
  if (ioctl(0, TCGETS, &saved_termios)) {
    perror("tcgets");
    exit(1);
  }

  signal(SIGINT, handler);
  signal(SIGQUIT, handler);

  tsave = 1;
  atexit(ttyfix);
  memcpy(&tw, &saved_termios, sizeof(struct termios));
  tw.c_lflag &= ~(ECHO|ECHOE|ECHOK|ECHONL|ICANON|ISIG);
  if (ioctl(0, TCSETS, &tw)) {
    perror("tcsets");
    exit(1);
  }
}

static int outit(int c)
{
  char x = c;
  write(1, &x, 1);
  return 0;
}

void clear_display(void)
{
  tputs(cl, rows, outit);
}

int move_cursor(int x, int y)
{
  if (*cm == 0)
    return 0;
  tputs(tgoto(cm, y, x), 2, outit);
  return 1;
}

void begin_input(void)
{
  ioctl(0, TCSETS, &saved_termios);
}

void end_input(void)
{
  ioctl(0, TCSETS, &tw);
}

