int main(int argc, char *argv[])
{
  int fd, l;
  struct stat s;

  if (argc != 2) {
    write(2, argv[0], strlen(argv[0]));
    write(2, ": program", 9);
    newline();
    exit(1);
  }

  visual_init();

  fd = open(argv[1], O_RDONLY);
  if (fd == -1 || fstat(fd, &s) == -1) {
    perror(argv[1]);
    exit(1);
  }
  if ((s.st_size|3) >= ~(size_t)0) {
    write(2, "File too large.", 15);
    newline();
    exit(1);
  }
  /* Align to the next quad */
  buf = sbrk((s.st_size|3) + 1);
  if (buf == (char *)-1) {
    write(2, "Out of memory.", 14);
    newline();
    exit(1);
  }
  l = read(fd, buf, s.st_size);
  if (l != s.st_size) {
    perror(argv[1]);
    exit(1);
  }
  close(fd);
  buf[l] = 0;
  run(buf);
  return 0;
}

