#define BUFF 256

int main(int argc, char ** argv)
{
    if(argc != 2)
    {
        printf("Usage: %s file", argv[0]);
        exit(1);
    }

    int fd, r, wr;
    char buf[BUFF];

    fd = open(argv[1], O_RDONLY);

    if(fd == -1)
    {
        perror(argv[1]);
        exit(2);
