    while( (r = read(fd, buf, BUFF)) > 0 && r != 1){
        if((wr = write(STDOUT_FILENO, buf, r))  <= 0 || wr != r){
            perror(argv[1]);
            close(fd);
            exit(3);
        }
    }

    close(fd);
    exit(0);


}

