#include <time.h>

#include "allocator.h"

static int seeded = 0;

static void ensure_seeded(void) {
  if (!seeded) {
    srandom(time(NULL));
    seeded = 1;
  }
}

float random_float(float min, float max) {
  ensure_seeded();
  return min + (max - min) * ((random() + 1.0) / 2147483647.0);
}

int random_int(int min, int max) {
  ensure_seeded();
  return min + random() % (max - min + 1);
}

