        tank_pointer = ADDR_LINK2DATA(node_pointer, tank, m_link) ;
        row = tank_pointer->m_position.y - y ;
        col = tank_pointer->m_position.x - x ;
        if((col>=0 ? col:0-col) > (row >= 0?row : 0-row) )
        {
            if(col < 0)
            {
                if(tank_move_check(tank_pointer, TANK_RIGHT))
