            {
                if(tank_move_check(tank_pointer, TANK_DOWN))
                {
                    tank_clear(tank_pointer) ;
                    tank_pointer->m_position.y += 1;
                    tank_draw(tank_pointer) ;
                }else {
                    if(col < 0)
                    {
                        if(tank_move_check(tank_pointer, TANK_RIGHT))
                        {
                            tank_clear(tank_pointer) ;
                            tank_pointer->m_position.x += 1;
                            tank_draw(tank_pointer) ;
