    {
        for(short height = 0; height < (short)(sizeof boss_pointer->m_body / sizeof boss_pointer->m_body[0]) ; height++)
        {
            if(height < (short)(sizeof boss_pointer->m_body / sizeof boss_pointer->m_body[0])/3)
