#ifndef OVR_KeyCodes_h
#define OVR_KeyCodes_h

namespace OVR {

//-----------------------------------------------------------------------------------
// ***** KeyCode

// KeyCode enumeration defines platform-independent keyboard key constants.
// Note that Key_A through Key_Z are mapped to capital ascii constants.

enum KeyCode {
  // Key_None indicates that no key was specified.
  Key_None = 0,

  // A through Z and numbers 0 through 9.
  Key_A = 65,
  Key_B,
  Key_C,
  Key_D,
  Key_E,
  Key_F,
  Key_G,
  Key_H,
  Key_I,
  Key_J,
  Key_K,
  Key_L,
  Key_M,
  Key_N,
  Key_O,
  Key_P,
  Key_Q,
  Key_R,
  Key_S,
  Key_T,
  Key_U,
  Key_V,
  Key_W,
  Key_X,
  Key_Y,
  Key_Z,
  Key_Num0 = 48,
  Key_Num1,
  Key_Num2,
  Key_Num3,
  Key_Num4,
  Key_Num5,
  Key_Num6,
  Key_Num7,
  Key_Num8,
  Key_Num9,

  // Numeric keypad.
  Key_KP_0 = 0xa0,
  Key_KP_1,
  Key_KP_2,
  Key_KP_3,
  Key_KP_4,
  Key_KP_5,
  Key_KP_6,
  Key_KP_7,
  Key_KP_8,
  Key_KP_9,
  Key_KP_Multiply,
  Key_KP_Add,
  Key_KP_Enter,
  Key_KP_Subtract,
  Key_KP_Decimal,
  Key_KP_Divide,

  // Function keys.
  Key_F1 = 0xb0,
  Key_F2,
  Key_F3,
  Key_F4,
  Key_F5,
  Key_F6,
  Key_F7,
  Key_F8,
  Key_F9,
  Key_F10,
  Key_F11,
  Key_F12,
  Key_F13,
  Key_F14,
  Key_F15,

  // Other keys.
  Key_Backspace = 8,
  Key_Tab,
  Key_Clear = 12,
  Key_Return,
  Key_Shift = 16,
  Key_Control,
  Key_Alt,
  Key_Pause,
  Key_CapsLock = 20, // Toggle
  Key_Escape = 27,
  Key_Space = 32,
  Key_Quote = 39,
  Key_PageUp = 0xc0,
  Key_PageDown,
  Key_End,
  Key_Home,
  Key_Left,
  Key_Up,
  Key_Right,
  Key_Down,
  Key_Insert,
  Key_Delete,
  Key_Help,

  // Synthetic mouse wheel state
  Key_MouseWheelAwayFromUser, // "forwards" or "up"
  Key_MouseWheelTowardUser, // "backwards" or "down"

  Key_Comma = 44,
  Key_Minus,
  Key_Slash = 47,
