					fetchGrid(i + 1, j, k) < 0 ||
					fetchGrid(i + 1, j, k + 1) < 0 ||
					fetchGrid(i + 1, j + 1, k) < 0 ||
					fetchGrid(i + 1, j + 1, k + 1) < 0)
					validCellNum++;
