static int prase_tlv_kv(uint8_t *addr, uint8_t **key, uint8_t **value)
{
    uint32_t type1, type2;
    uint32_t length1, length2;
    uint8_t *key_tmp, *value_tmp;
    int off = 0;

    /* check arg */
    if ((!addr) || (!key) || (!value)) {
        //printf("prase_tlv_kv arg error.\r\n");
        return -1;
    }

    type1 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    length1 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    key_tmp = (uint8_t *)(addr + off);
    off += length1;
    if (type1 != TLV_TYPE_KEY) {
        printf("not key type type1 = 0x%04lx\r\n", type1);
        return -2;
    }

    type2 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    length2 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    value_tmp = (uint8_t *)(addr + off);
    off += length2;
    if (type2 != TLV_TYPE_VALUE) {
        printf("not value type2 = 0x%04lx\r\n", type2);
        return -3;
    }

    *key = key_tmp;
    *value = value_tmp;
    return off;
}

/*
 * output
 *     version
 * return
 *     0-success
 */
static int prase_tlv_version(uint8_t *addr, uint8_t **version)
{
    uint32_t type1, length1;
    uint8_t *value_tmp;
    int off = 0;

    /* check arg */
    if ((!addr) || (!version)) {
        printf("prase_tlv_version arg error.\r\n");
        return -1;
    }

    type1 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    length1 = *(uint32_t *)(addr + off);
    off += sizeof(uint8_t *);
    value_tmp = (uint8_t *)(addr + off);
    off += length1;
    if (type1 != TLV_TYPE_VERSION) {
        printf("not key type.\r\n");
        return -2;
    }

    *version = value_tmp;
    return off;
}

