}

inline static void initial_output(float* output, float* bias, int output_ch, int output_wh)
{
    int i, j;

    // no bias
    if (bias == NULL)
    {
        memset(output, 0.f, output_ch * output_wh * sizeof(float));
    }
    else
    {
        float* out_ptr = output;

        for (i = 0; i < output_ch; i++)
