                cur_out2[3] += val * cur_kernel[11];

                cur_out3[0] += val * cur_kernel[12];
                cur_out3[1] += val * cur_kernel[13];
                cur_out3[2] += val * cur_kernel[14];
                cur_out3[3] += val * cur_kernel[15];

                cur_input++;
                cur_out0++;
