DBL_TYPE nsStarFull( char prefix[], int seq[], int complexity, int naType, 
                     int dangles, DBL_TYPE temperature, DBL_TYPE sodiumconc,
		     DBL_TYPE magnesiumconc, int uselongsalt) {

  int size;
