char * intToRoman(int num) {

    char items[13][3] = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
    int values[] = {1000,900,500,400,100,90,50,40,10,9,5,4,1};
    char *result = (char *)malloc(20 * sizeof(char));
    for (int i = 0; i < 20; i++) {
        result[i] = '\0';
    }

    for (int i = 0; num != 0; i++) {
        while (num >= values[i]) {
            num -= values[i];
            strcat(result, items[i]);
        }
    }
    return result;
}


