void init_grid(void) {
/* Allocate and set up the grid */
    int  nx = params->nx;
    int  ny = params->ny;
    int  nz = params->nz;
    int  size = nx*ny*nz;

    grid = (Grid *)malloc(sizeof(Grid));

    grid->xmin = (double *)malloc(sizeof(double)*(nx+1));
