void log_output(log_level level, const char* message, ...)
{
    const char* level_strings[6] = {"[FATAL]: ", "[ERROR]: ", "[WARN]: ", "[INFO]: ", "[DEBUG]: ", "[TRACE]: "};
    b8 is_error = level < LOG_LEVEL_WARN;

    // Imposes a 32 thousand character limit on a single log entry.
    const i32 message_length = 32000;
    char out_message[message_length];
    memset(out_message, 0, sizeof(out_message));

    // Format original message.
    // NOTE: Microsoft's headers override the GCC/Clang va_list type with a "typedef char* va_list" in some cases,
    // and as a result throws a strange error here. The workaround is to just use __builtin_va_list,
    // which is the type GCC/Clang's va_start expects.
    __builtin_va_list arg_ptr;
    va_start(arg_ptr, message);
    vsnprintf(out_message, message_length, message, arg_ptr);
    va_end(arg_ptr);

    char out_message2[message_length];
    sprintf(out_message2, "%s%s\n", level_strings[level], out_message);

    // Platform specific output.
    if (is_error)
    {
        platform_console_write_error(out_message2, level);
    }
    else
    {
        platform_console_write(out_message2, level);
    }
}

void report_assertion_failure(const char* expression, const char* message, const char* file, i32 line)
{
    log_output(LOG_LEVEL_FATAL, "Assertion Failure: %s, message: '%s', in file: %s, line: %d\n", expression, message, file, line);
}

