	       0, SAHPI_CTRL_MAX_STREAM_LENGTH);
        memcpy(	ctrl_stream_context->saHpiCtrlStreamState,
		rdr_entry->RdrTypeUnion.CtrlRec.TypeUnion.Stream.Default.Stream,
		rdr_entry->RdrTypeUnion.CtrlRec.TypeUnion.Stream.Default.StreamLength);
        ctrl_stream_context->saHpiCtrlStreamState_len = 
		rdr_entry->RdrTypeUnion.CtrlRec.TypeUnion.Stream.Default.StreamLength;

        /** UNSIGNED32 = ASN_UNSIGNED */
        ctrl_stream_context->saHpiCtrlStreamOem = 
		rdr_entry->RdrTypeUnion.CtrlRec.Oem;

        /** RowPointer = ASN_OBJECT_ID */
	memset(ctrl_stream_context->saHpiCtrlStreamRDR, 
	       0, 
	       sizeof(ctrl_stream_context->saHpiCtrlStreamRDR));

	ctrl_stream_context->saHpiCtrlStreamRDR_len = full_oid_len * sizeof(oid);
	memcpy(ctrl_stream_context->saHpiCtrlStreamRDR, 
	       full_oid, 
	       ctrl_stream_context->saHpiCtrlStreamRDR_len);

	if (new_row == MIB_TRUE)
                CONTAINER_INSERT (cb.container, ctrl_stream_context);

	ctrl_stream_entry_count = CONTAINER_SIZE (cb.container);

        subagent_unlock(&hpi_lock_data);

	return rv;
}

/**
 * 
 * @domainId
 * @resourceId
 * 
 * @return 
 */
SaErrorT clear_ctrl_stream(SaHpiDomainIdT domainId, 
                           SaHpiResourceIdT resourceId)

{
        SaErrorT rv = SA_OK;
        netsnmp_index *row_idx;
        saHpiCtrlStreamTable_context *ctrl_ctx;

	DEBUGMSGTL ((AGENT, "clear_ctrl_stream, called\n"));	
	DEBUGMSGTL ((AGENT, "           domainId   [%d]\n", domainId));	
	DEBUGMSGTL ((AGENT, "           resourceId [%d]\n", resourceId));

        DR_XREF *dr_entry;
        SaHpiDomainIdResourceIdArrayT dr_pair;

        /* reset any existing indexEntry value */
        dr_pair.domainId_resourceId_arry[0] = domainId;
        dr_pair.domainId_resourceId_arry[1] = resourceId;
        dr_entry = domain_resoruce_pair_lookup(&dr_pair, &dr_table); 
        if (dr_entry == NULL) {
                DEBUGMSGTL ((AGENT, 
                "INFO: clear_ctrl_stream() domain_resource_pair_get returned NULL\n"));
                return SA_ERR_HPI_NOT_PRESENT;
        } else {
                dr_entry->entry_id = 0;
        }

        row_idx = CONTAINER_FIRST(cb.container);
        if (row_idx) //At least one entry was found.
        {
                do {
                        /* based on the found row_idx get the pointer   */
                        /* to its context (row data)                    */
                        ctrl_ctx = CONTAINER_FIND(cb.container, row_idx);

                        /* before we delete the context we should get the  */
                        /* next row (context) if any before we delete this */ 
                        /* one.                                            */
                        row_idx = CONTAINER_NEXT(cb.container, row_idx);

                        if ((ctrl_ctx->index.oids[saHpiCtrlStreamDomainId_INDEX] ==
                             domainId) &&

                            (ctrl_ctx->index.oids[saHpiCtrlStreamResourceEntryId_INDEX] ==
                             resourceId)) {

                                /* all conditions met remove row */
                                CONTAINER_REMOVE (cb.container, ctrl_ctx);
                                saHpiCtrlStreamTable_delete_row (ctrl_ctx);
                                ctrl_stream_entry_count = 
                                        CONTAINER_SIZE (cb.container);
                                DEBUGMSGTL ((AGENT, "clear_ctrl_stream: "
                                                    "found row: removing\n"));

                        }

                } while (row_idx);
        } 

        return rv;
}

/*
 * int set_table_ctrl_analog_mode();
 */
int set_table_ctrl_stream (saHpiCtrlStreamTable_context *row_ctx)
{
	SaErrorT            rc = SA_OK;
	SaHpiSessionIdT     session_id;
	SaHpiResourceIdT    resource_id;
	SaHpiCtrlStateT	    ctrl_state;	

	DEBUGMSGTL ((AGENT, "set_table_ctrl_stream_mode, called\n"));	

	if (!row_ctx)
		return AGENT_ERR_NULL_DATA;

	session_id = get_session_id(row_ctx->index.oids[saHpiCtrlStreamDomainId_INDEX]);
	resource_id = row_ctx->index.oids[saHpiCtrlStreamResourceEntryId_INDEX];

	/* repeat */
	ctrl_state.StateUnion.Stream.Repeat = row_ctx->saHpiCtrlStreamRepeat;

	/* stream */
	memset(ctrl_state.StateUnion.Stream.Stream, 0, 
	       sizeof(ctrl_state.StateUnion.Stream.Stream));
	memcpy(ctrl_state.StateUnion.Stream.Stream,
	       row_ctx->saHpiCtrlStreamState, 
	       row_ctx->saHpiCtrlStreamState_len);

	/* stream length */
	ctrl_state.StateUnion.Stream.StreamLength = row_ctx->saHpiCtrlStreamState_len;

	/* type */
	ctrl_state.Type = SAHPI_CTRL_TYPE_STREAM;

	rc = saHpiControlSet(session_id, resource_id, 
			     row_ctx->saHpiCtrlStreamNum, 
			     row_ctx->saHpiCtrlStreamMode - 1, 
			     &ctrl_state); 

	if (rc != SA_OK) {
		snmp_log (LOG_ERR,
			  "SAHPI_CTRL_TYPE_STREAM: Call to saHpiControlSet failed to set Mode rc: %s.\n",
			  oh_lookup_error(rc));
		DEBUGMSGTL ((AGENT,
			     "SAHPI_CTRL_TYPE_STREAM: Call to saHpiControlSet failed to set Mode rc: %s.\n",
			     oh_lookup_error(rc)));
		return get_snmp_error(rc);
	} 

	return SNMP_ERR_NOERROR; 
}

/*
 * int handle_saHpiCtrlStreamActiveEntries()
 */
int handle_saHpiCtrlStreamActiveEntries(netsnmp_mib_handler *handler,
				     netsnmp_handler_registration *reginfo,
				     netsnmp_agent_request_info   *reqinfo,
				     netsnmp_request_info         *requests)
{
    /* We are never called for a GETNEXT if it's registered as a
       "instance", as it's "magically" handled for us.  */

    /* a instance handler also only hands us one request at a time, so
       we don't need to loop over a list of requests; we'll only get one. */

    ctrl_stream_entry_count = CONTAINER_SIZE (cb.container);

    switch(reqinfo->mode) {

        case MODE_GET:
            snmp_set_var_typed_value(requests->requestvb, ASN_GAUGE,
                                     (u_char *) &ctrl_stream_entry_count,
				     sizeof(ctrl_stream_entry_count));
            break;


        default:
            /* we should never get here, so this is a really bad error */
            return SNMP_ERR_GENERR;
    }

    return SNMP_ERR_NOERROR;
}

/*
 * int initialize_table_saHpiCtrlStreamActiveEntries(void)
