			"saHpiCtrlStreamActiveEntries", 
			handle_saHpiCtrlStreamActiveEntries,
                        saHpiCtrlStreamActiveEntries_oid, 
			OID_LENGTH(saHpiCtrlStreamActiveEntries_oid),
                        HANDLER_CAN_RONLY));
	return 0;
}

