        {
            return 5;
        }

        ROOT::Math::IBaseFunctionMultiDim* Clone() const
        {
            ROOT::Math::IBaseFunctionMultiDim* clone = new VFun_SourceDescription_RadialAsymmetricSource_LL( hSkyMap, xmin, xmax, ymin, ymax, sigmaPSF );
