				{
					return other.size == size && other.raw_index == raw_index && other.hireg == hireg && other.newreg == newreg;
				}

				inline bool operator!=(const X86Register& other) const
				{
					return !(other.size == size && other.raw_index == raw_index && other.hireg == hireg && other.newreg == newreg);
