 extern int SIerrno;
 char *p;

 for( p = buf; *p && *p != '\n'; p++ );    /* stop at first new line */
 *p = 0;

 if(  strncmp( buf, "stop", 4 ) == 0 )
  {
   printf( "Stopping\n" );
   status = SI_RET_QUIT;
  }
 else
 if(  strncmp( buf, "quit", 4 ) == 0 )
  {
   printf( "Stopping\n" );
   status = SI_RET_QUIT;
  }
 else
 if(  strncmp( buf, "exit", 4 ) == 0 )
  {
   printf( "Stopping\n" );
   status = SI_RET_QUIT;
  }
 else
  if( strncmp( buf, "conn ", 5 ) == 0 )
