/**********************************************************************
 * complex function management code :
 **********************************************************************/
void really_destroy_complex_func (ComplexFunction * cf)
{
	if (cf) {
		if (cf->magic == MAGIC_COMPLEX_FUNC) {
			register int i;

			cf->magic = 0;
			if (cf->name)
				free (cf->name);
			if (cf->items) {
				for (i = 0; i < cf->items_num; i++)
					free_func_data (&(cf->items[i]));
				free (cf->items);
			}
			free (cf);
		}
	}
}

void complex_function_destroy (ASHashableValue value, void *data)
{
	ComplexFunction *cf = data;

	if ((char *)value)
		free ((char *)value);
	if (cf && cf->magic == MAGIC_COMPLEX_FUNC) {
		if (cf->name == (char *)value)
			cf->name = NULL;
		really_destroy_complex_func (cf);
	} else if (data)
		free (data);
}

void init_list_of_funcs (struct ASHashTable **list, Bool force)
{
	if (list == NULL)
		return;

	if (force && *list != NULL)
		destroy_ashash (list);

	if (*list == NULL)
		*list =
				create_ashash (0, casestring_hash_value, casestring_compare,
											 complex_function_destroy);
}

/* list could be NULL here : */
ComplexFunction *new_complex_func (struct ASHashTable *list, char *name)
{
	ComplexFunction *cf = NULL;

	if (name == NULL)
		return NULL;
	/* enlisting complex function is optional */
	cf = (ComplexFunction *) safecalloc (1, sizeof (ComplexFunction));
	cf->name = mystrdup (name);
	cf->magic = MAGIC_COMPLEX_FUNC;
	if (list) {
		remove_hash_item (list, AS_HASHABLE (name), NULL, True);	/* we want only one copy */
		if (add_hash_item (list, AS_HASHABLE (cf->name), cf) != ASH_Success) {
			really_destroy_complex_func (cf);
			cf = NULL;
		}
	}
	return cf;
}

ComplexFunction *find_complex_func (struct ASHashTable * list, char *name)
{
	ASHashData hdata = { 0 };
	if (name && list)
		if (get_hash_item (list, AS_HASHABLE (name), &hdata.vptr) !=
				ASH_Success)
			hdata.vptr = NULL;				/* we are being paranoid */
	return (ComplexFunction *) hdata.vptr;
}

