#endif


/* replace output handlers with unit test versions
*/
#undef MIPI_SYST_OUTPUT_D32MTS
#undef MIPI_SYST_OUTPUT_D64MTS
#undef MIPI_SYST_OUTPUT_D32TS
#undef MIPI_SYST_OUTPUT_D8
#undef MIPI_SYST_OUTPUT_D16
