                        data, detail::simdlib::vshlq<1>)};
            case 2:
                return simd16uint16{detail::simdlib::unary_func(
                        data, detail::simdlib::vshlq<2>)};
            case 3:
                return simd16uint16{detail::simdlib::unary_func(
