        return simd16uint16{
                detail::simdlib::binary_func(data, other.data, &vsubq_u16)};
    }

    template <
            typename T,
            typename std::enable_if<
                    detail::simdlib::is_simd256bit<T>::value,
                    std::nullptr_t>::type = nullptr>
    simd16uint16 operator&(const T& other) const {
