	md_copy_strides(N, tostr, ostr);
	tostr[d] = x * ostr[d];
	tostr[N] = ostr[d];

	long pdims[N + 1];
	md_select_dims(N + 1, MD_BIT(d) | MD_BIT(N), pdims, tdims);

	long pstr[N + 1];
	md_calc_strides(N + 1, pstr, pdims, CFL_SIZE);

	complex float* shift = md_alloc_sameplace(N + 1, pdims, CFL_SIZE, src);

	float pos[N];
	for (int i = 0; i < N; i++)
		pos[i] = 0.;

	for (int i = 0; i < x; i++) {

