int length(char *s)
{
	int i=0;
	while(s[i]!='\0')
	{
		i++;
	}
	return i;
}

void Insert(char *str, char *sub, int pos)
{
	int i=-1;
	int len = length(str);
	char temp[100];
	do
	{
		i++;
		temp[i]=str[i];
	}while(i!=len);

	int sublen=length(sub);
	int j = pos;

	for(i=0;i<sublen;i++)
	{
		str[j++]=sub[i];
	}

	for(i=pos;i<=len;i++)
	{
		str[j++]=temp[i];
	}
}

//returns the position of a in str
int charCheck (char * str , char a ,int i )
{
	if(str[i]==a)
			return i;
	else 
		return -1;

}

int main()
{

    char str[100];


    int i =-1,start=0;

    scanf("%s",str);

    char c1;
    scanf("\n%c",&c1); 

    char subs1[50];
    scanf("%s",subs1);


    for(i=0;i<length(str);i++)
    {
