int main(int argc, char const *argv[])
{
	int graph[N][N] = { { 0, 10, 15, 20 }, 
                       { 10, 0, 35, 25 }, 
                       { 15, 35, 0, 30 }, 
                       { 20, 25, 30, 0 } }; 

	int result;
	struct timespec start, end;

