    element.step = 0;
    if (element.state > STATE_HIDDEN)
    {
       element.y -=1;
       switch (element.state)
       {
          case BULLET_L_MOVE:
          if (element.x < 64) {
            if (element.x > 32) element.step = 1;
            if (element.x > 48) element.step = 2;
            element.x +=4;
          } else {
            element.state = STATE_HIDDEN;
          }
          break;

          case BULLET_R_MOVE:
          if (element.x > 64) {
            if (element.x < 96) element.step = 1;
            if (element.x < 80) element.step = 2;
            element.x -=4;
          } else {
            element.state = STATE_HIDDEN;
          }
