#include <stdio.h>

void ShellSort_1(int* nums, int q, int r) {
    int numsSize = r - q + 1;
    int i, j, temp;
    int* p;
    int interval[] = {		// Sedgewick增量
          1073643521, 603906049, 268386305, 150958081, 67084289,
          37730305, 16764929, 9427969, 4188161, 2354689,
          1045505, 587521, 260609, 146305, 64769,
          36289, 16001, 8929, 3905, 2161,
          929, 505, 209, 109, 41,
          19, 5, 1, 0};
    for (p = interval; *p > numsSize; p++);
    while (*p != 0) {
        for (i = *p + q; i < numsSize + q; i++) {
            temp = nums[i];
            for (j = i - *p; j >= q && nums[j] > temp; j -= *p) {
                nums[j + *p] = nums[j];
                nums[j] = temp;
            }
        }
        p++;
    }
}

