// Command mode RW=0, RS=0, En=1 then EN=0
void cmd(int c) {
  IOPIN0 = c << 15; // Sending data(cmd) to data pins
  IOCLR0 = RW;
  IOCLR0 = RS;
  IOSET0 = EN;
  delay(25);
  IOCLR0 = EN;
}

