	byte_buf = SPI_transmit(0xFF);
	ID |= ( ((uint64_t)byte_buf) << 16 );
	byte_buf = SPI_transmit(0xFF);
	ID |= ( ((uint64_t)byte_buf) << 8 );
	byte_buf = SPI_transmit(0xFF);
	ID |= ( ((uint64_t)byte_buf) << 0 );
	// CS high, transmission finished
	CS_HIGH();
	return ID;
