#include <sys/cdefs.h>
#include <sys/systm.h>
#include <arm/stm/stm32f4_flash.h>
#include <arm/stm/stm32f4_pwr.h>
#include <arm/stm/stm32f4_rcc.h>

#define	RD4(_sc, _reg)		\
	*(volatile uint32_t *)((_sc)->base + _reg)
#define	WR4(_sc, _reg, _val)	\
	*(volatile uint32_t *)((_sc)->base + _reg) = _val

void
stm32f4_rcc_eth_reset(struct stm32f4_rcc_softc *sc)
{
	uint32_t reg;

	/* Reset ethernet controller */
	reg = RD4(sc, RCC_AHB1RSTR);
	reg |= (ETHMACRST);
	WR4(sc, RCC_AHB1RSTR, reg);

	udelay(10000);

	reg &= ~(ETHMACRST);
	WR4(sc, RCC_AHB1RSTR, reg);
}

void
stm32f4_rcc_pllsai(struct stm32f4_rcc_softc *sc,
    uint32_t sain, uint32_t saiq, uint32_t sair)
{
	uint32_t reg;

	reg = (sain << PLLSAICFGR_PLLSAIN_S);
	reg |= (saiq << PLLSAICFGR_PLLSAIQ_S);
	reg |= (sair << PLLSAICFGR_PLLSAIR_S);
	WR4(sc, RCC_PLLSAICFGR, reg);

	reg = (0x2 << DCKCFGR_PLLSAIDIVR_S);
	WR4(sc, RCC_DCKCFGR, reg);

	reg = RD4(sc, RCC_CR);
	reg |= CR_PLLSAION;
	WR4(sc, RCC_CR, reg);
	while ((RD4(sc, RCC_CR) & CR_PLLSAIRDY) == 0)
		;
}

void
stm32f4_rcc_pll_configure(struct stm32f4_rcc_softc *sc,
    int pllm, int plln, int pllq, int pllp, uint8_t external,
    uint32_t rcc_cfgr)
{
	uint32_t reg;

	if (external) {
		/* Use external ocsillator */
		reg = RD4(sc, RCC_CR);
		reg |= CR_HSEON;
		WR4(sc, RCC_CR, reg);
		while ((RD4(sc, RCC_CR) & CR_HSERDY) == 0)
			;
	} else {
		reg = RD4(sc, RCC_CR);
		reg |= (CR_HSION);
		WR4(sc, RCC_CR, reg);
		while ((RD4(sc, RCC_CR) & CR_HSIRDY) == 0)
			;
	}

	WR4(sc, RCC_CFGR, rcc_cfgr);

	reg = (pllm << PLLCFGR_PLLM_S);
	reg |= (plln << PLLCFGR_PLLN_S);
	reg |= (pllq << PLLCFGR_PLLQ_S);
	reg |= (pllp << PLLCFGR_PLLP_S);
	if (external)
		reg |= PLLCFGR_PLLSRC_HSE;
	WR4(sc, RCC_PLLCFGR, reg);

	reg = RD4(sc, RCC_CR);
	reg |= CR_PLLON;
	WR4(sc, RCC_CR, reg);
	while ((RD4(sc, RCC_CR) & CR_PLLRDY) == 0)
		;
}

int
stm32f4_rcc_setup(struct stm32f4_rcc_softc *sc, uint32_t ahb1enr,
    uint32_t ahb2enr, uint32_t ahb3enr, uint32_t apb1enr,
    uint32_t apb2enr)
{
	uint32_t reg;

	reg = RD4(sc, RCC_CFGR);
	reg &= ~(CFGR_SW_M);
	reg |= CFGR_SW_PLLP;
	WR4(sc, RCC_CFGR, reg);

	while ((RD4(sc, RCC_CFGR) & CFGR_SWS_M) != CFGR_SWS_PLL)
		;

	reg = RD4(sc, RCC_AHB1ENR);
	reg |= ahb1enr;
	WR4(sc, RCC_AHB1ENR, reg);

	reg = RD4(sc, RCC_AHB2ENR);
	reg |= ahb2enr;
	WR4(sc, RCC_AHB2ENR, reg);

	reg = RD4(sc, RCC_AHB3ENR);
	reg |= ahb3enr;
	WR4(sc, RCC_AHB3ENR, reg);

	reg = RD4(sc, RCC_APB1ENR);
	reg |= apb1enr;
	WR4(sc, RCC_APB1ENR, reg);

	reg = RD4(sc, RCC_APB2ENR);
	reg |= apb2enr;
	WR4(sc, RCC_APB2ENR, reg);

	return (0);
}

int
stm32f4_rcc_init(struct stm32f4_rcc_softc *sc, uint32_t base)
{

	sc->base = base;

	return (0);
}

