int iSqrt(int x) {

	if (x >= 0x10000) {

		if (x >= 0x1000000) {

			if (x >= 0x10000000) {

				if (x >= 0x40000000) {

					return (table[x >> 24] << 8);

				} else {

					return (table[x >> 22] << 7);

				}

			} else if (x >= 0x4000000) {

				return (table[x >> 20] << 6);

			} else {

