  DECL_GL_FUNC_PTR(GLenum,glGetError,(void));

  LOAD_GL_FUNC(glGetError, NULL);
	error = fptr_glGetError();

	if (error==GL_NO_ERROR) { /* no errors == instant return */
		return;
	} else { /* process errors */
		const char *error_string;
		const char *from = "";
