    // if (res < STATE_SUCCESS) {
    //     printf("aiot_subdev_send_sub_register failed, res: -0x%04X\n", -res);
    //     aiot_subdev_deinit(&subdev_handle);
    //     demo_mqtt_stop(&mqtt_handle);
