          assert pay_ccs == msg_ccs;        }
    @*/

    //@ chars_join(buffer);
    free(buffer);
    zeroize(hmac, 64);
    zeroize(buffer_dec, enc_size - 64);
    zeroize(buffer_dec + enc_size - 64, 64);
    free(buffer_dec);
  }
  net_close(socket2);
  net_close(socket1);
  return enc_size - 64;
  //@ close principal(receiver, _);
}

