#define MAX_CHARS_PER_ACCT	5

	// Some messages are bydirectional.

	union
	{
		BYTE m_Raw[ MAX_BUFFER ];

		DWORD m_CryptHeader;	// This may just be a crypt header from the client.

		struct
		{
			BYTE m_Cmd;		// XCMD_TYPE, 0 = ?
			BYTE m_Arg[1];	// unknown size.
		} Default;	// default unknown type.

		struct	// XCMD_Create, size = 100	// create a new char
		{
			BYTE m_Cmd;		// 0=0
			BYTE m_unk1[9];
			char m_charname[MAX_NAME_SIZE];		// 10
			char m_charpass[MAX_NAME_SIZE];		// 40

			BYTE m_sex;		// 70, 0 = male
			BYTE m_str;		// 71
			BYTE m_dex;		// 72
			BYTE m_int;		// 73

			BYTE m_skill1;
			BYTE m_val1;
			BYTE m_skill2;
			BYTE m_val2;
			BYTE m_skill3;
			BYTE m_val3;

			NWORD m_wSkinHue;	// 0x50 // HUE_TYPE
			NWORD m_hairid;
			NWORD m_hairHue;
			NWORD m_beardid;
			NWORD m_beardHue;	// 0x58
			NWORD m_startloc;	// 0x5B
			NWORD m_unk5c;
			NWORD m_slot;
			BYTE m_clientip[4];
		} Create_v25;

		struct	// XCMD_Create, size = 100	// create a new char
		{
			BYTE m_Cmd;		// 0=0
			BYTE m_unk1[9];
			char m_charname[MAX_NAME_SIZE];		// 10
			char m_charpass[MAX_NAME_SIZE];		// 40

			BYTE m_sex;		// 70, 0 = male
			BYTE m_str;		// 71
			BYTE m_dex;		// 72
			BYTE m_int;		// 73

			BYTE m_skill1;
			BYTE m_val1;
			BYTE m_skill2;
			BYTE m_val2;
			BYTE m_skill3;
			BYTE m_val3;

			NWORD m_wSkinHue;	// 0x50 // HUE_TYPE
			NWORD m_hairid;
			NWORD m_hairHue;
			NWORD m_beardid;
			NWORD m_beardHue;	// 0x58
			BYTE m_unk2;
			BYTE m_startloc;
			BYTE m_unk3;
			BYTE m_unk4;
			BYTE m_unk5;
			BYTE m_slot;
