double GridFun2D::normInf(){
    double maximum = fabs(values(0,0));
    for(long i = 0; i < values.getIndex1Size(); i++){
        for(long j = 0; j < values.getIndex2Size(); j++){
            if(fabs(values(i,j)) > maximum){
                maximum = fabs(values(i,j));
            }
        }
    }
    return maximum;
