void vpxlog_dbg_no_head(int level, const tc8 *format, ...)
{
    va_list list;

    if (!(level & LOG_MASK))
        return;

    va_start(list, format);

    vprintf(format, list);
    va_end(list);
}

void vpxlog_dbg(int level, const tc8 *format, ...)
{
    va_list list;

    if (!(level & LOG_MASK))
        return;

    if (start_time == 0)
        start_time = get_time();

    printf("%8d ", get_time() - start_time);
    va_start(list, format);

    vprintf(format, list);
    va_end(list);
}

