	struct sbefifo_context *sctx = sbefifo->get_sbefifo_context(sbefifo);
	uint8_t core_id;

	core_id = sbefifo_core_id(sctx, thread);

	return sbefifo_register_put(sctx,
				    core_id,
				    thread->id,
				    reg_type,
				    &reg_id,
				    1,
				    &value);
}

