	} else {
		CvScalar colRgb1 = cvScalar(250, 200, 200, 0);
		CvScalar colRgb2 = cvScalar(200, 250, 200, 0);
		limpiarImg_cuadriculadoColor(bg_rgb, colRgb1, colRgb2);
	}
	int64_t code = getCvtCode_rgb_cshist(es);
