void test_tail_proj_approx() {
    Data *graph = read_mnist_data();
    PruningMethod pruning = GWPruning;
    int g = 1, sparsity = 100, max_iter = 50, root = -1, n = graph->p;
    int m = graph->m, verbose = 0;
