inline void ColumnMultiply(Iterator<VALUE> column, Iterator<WMap> mt,
						   Vector<VALUE> &product)  
{
  product.reset();
  for ( ; mt; ++mt)  {
         VALUE  TmpResult= 0;
         Iterator<WPair> it= (*mt)();
         for ( ; it; ++it)
           TmpResult += column[(*it).first] * (*it).second;
         product << TmpResult;
  };
  return;
}

