void mctrl_init()
{
	TWI_init();

	char msg[32];
	sprintf( msg, "%cGRBL v%s %s", CMD_MESSAGE, GRBL_VERSION, GRBL_VERSION_BUILD);
	TWI_putOp( MCTRL_I2C_ADDR, I2C_WRITE, (uint8_t*) msg, strlen( msg), 0);
//	TWI_triggerSend();
}

void mctrl_u8Cmd( uint8_t b) {
	TWI_putOp( MCTRL_I2C_ADDR, I2C_WRITE, &b, 1, 0);
//	TWI_triggerSend();
}

void mctrl_u16Cmd( uint16_t b) {
	uint8_t val[2];

	val[0] = (b >> 8) & 0xff;
	val[1] = b & 0xff;
	TWI_putOp( MCTRL_I2C_ADDR, I2C_WRITE, val, 2, 0);
//	TWI_triggerSend();
}

uint8_t mctrl_limitNorm( uint8_t limits) {
	uint8_t i, msg = 0x00, mask = 0x01, bit = 0x01;

	// "XYZUVW";
	for( i = 0; i < 6; i++) {
		if (limits & mask) msg |= bit;
		if ( i == 1) mask <<= 3;
		else mask <<= 1;
		bit <<= 1;
	}

	return msg;
}

void mctrl_limitStatus( uint8_t limits) {
	char msg[2];

	msg[0] = CMD_MESSAGE | CMD_MSG_LIM;
	msg[1] = mctrl_limitNorm( limits);

	TWI_putOp( MCTRL_I2C_ADDR, I2C_WRITE, (uint8_t*) msg, 2, 0);
}

void mctrl_msgCmd( uint8_t tidx) {
	char msg[64];

//	sprintf( msg, "%cT%i R[%5.2f]  Z[%6.2f]" , CMD_MESSAGE, tidx, gc_state.tool_table[tidx].r, gc_state.tool_table[tidx].xyz[2]);
