	ARGBEGIN {
	case 'a': aflag = 1; break;
	case 'd': dflag = 1; break;
	case 'l': lflag = 1; break;
	case 's': sflag = 1; break;
	case 't': tflag = 1; break;
	case 'u': uflag = 1; break;
	case 'v': vflag = 1; break;
