      XORI_B_4VECS_UB(out0_r, out1_r, out2_r, out3_r,
                      tmp0, tmp1, tmp2, tmp3, 128);

      STORE_4VECS_UB(dst_tmp, dst_stride, tmp0, tmp1, tmp2, tmp3);
      dst_tmp += (4 * dst_stride);

      src10_r = src54_r;
      src32_r = src76_r;
      src54_r = src98_r;
      src21_r = src65_r;
      src43_r = src87_r;
      src65_r = src109_r;

