void CNFGUpdateScreenWithBitmap( unsigned long * data, int w, int h )
{
	RECT r;

	int a = SetBitmapBits(lsBitmap,w*h*4,data);
	a = BitBlt(lsWindowHDC, 0, 0, w, h, lsHDC, 0, 0, SRCCOPY);
