    y = 0x40;

    k = -1;
    for (j = 1; j < n; ++j)
    for (i = 0; i < j; ++i)
    {
        if (++k == 6)
        {
            *(sp++) = y;
            y = 0x40;
            k = 0;
        }
        if (g[i] & bit[j]) y |= ybit[k];
    }
    if (n >= 2) *(sp++) = y;
    *(sp++) = '\n';
    *sp = '\0';

    if (fputs(s,f) == EOF || ferror(f))
    {
        fprintf(stderr,">E writeny : error on writing file\n");
        exit(2);
    }
}

