	u32 sc_ch = 0;
	bool in_use = FALSE;

	for (sc_ch = 0; sc_ch < MAXSC; sc_ch++) {
		ret = nss_macsec_secy_tx_sc_in_used_get(drv->secy_id, sc_ch,
							&in_use);
