Tableau nb_mot_fic(char* fic){
  char c;
  int est_mot = 0;
  Tableau t;
  FILE* f = fopen(fic, "r");

  if(f == NULL){
    fprintf(stderr, "Erreur ouverture fichier %s\n", fic);
    exit(EXIT_FAILURE);
  }

  t.n = 0;
  t.taille = 0;
  t.tab = NULL;

  while((c = fgetc(f)) != EOF){
    if(isalpha(c)){
      est_mot++;
    }
    else{
      if(est_mot){
	t.n++;
	if(est_mot > t.taille){
	  t.taille = est_mot;
	}
	est_mot = 0;
      }
    }
  }
  fclose(f);
  t.taille++; //on ajoute 1 pour stocker le caractere de fin de chaine
  return t;
}

