      est_mot = 1;
    }
    else{
      if(est_mot){
	est_mot = 0;
	i = 0;
	j++;
      }
    }
  }
  fclose(f);

  return t;
}


void affiche_tab(Tableau t){
  int i;
  for(i=0; i<t.n; i++)
    printf("%s\n",t.tab[i]);
}



//retourne une copie du tableau
Tableau copy_tab(Tableau t){
  int i,j;
  char** tsauv = t.tab;
  char* p;

  //allocation memoire
  t.tab = calloc(1,t.n*sizeof(char*)+t.n*t.taille);
  if(t.tab == NULL){
    fprintf(stderr, "Erreur allocation tableau\n");
    exit(EXIT_FAILURE);
  }
  p = (char*) (t.tab+t.n);
  for(i=0; i<t.n; i++)
    t.tab[i] = p + i*t.taille;

  //recopie
  for(i=0; i<t.n; i++){
    for(j=0; j<t.taille; j++){
      t.tab[i][j] = tsauv[i][j];
    }
  }

  return t;
}


Tableau libere_tab(Tableau t){
  free(t.tab);
  t.tab = NULL;
  return t;
}

