	vertices[i++] = v[0].x; vertices[i++] = v[0].y; vertices[i++] = v[0].z; vertices[i++] = 0; vertices[i++] = 0;
	vertices[i++] = v[1].x; vertices[i++] = v[1].y; vertices[i++] = v[1].z; vertices[i++] = 1; vertices[i++] = 0;

