	GL_CHECK( glBindBuffer( GL_ARRAY_BUFFER, vbo ) );
	GL_CHECK( glBufferData( GL_ARRAY_BUFFER, sizeof( vertices ), vertices, GL_DYNAMIC_DRAW ) );

	GLuint shaderProgram = shaders[shader].program;
