	whitgl_iaabb n = {rect.a, {rect.b.x, rect.a.y+width}};
	whitgl_iaabb e = {{rect.b.x-width, rect.a.y}, rect.b};
	whitgl_iaabb s = {{rect.a.x, rect.b.y-width}, rect.b};
