  c->startTrigger.triggerType = TRIG_ABSTIME;
  c->startTime = start_time;
  c->pOutput = (rfc_ble5ScanInitOutput_t *)output;

  c->txPower = tx_power;
  c->rangeDelay = 0;
#else
