/*---------------------------------------------------------------------------*/
void
rf_ble_cmd_create_master_params(uint8_t *params, dataQueue_t *rx_queue,
                                dataQueue_t *tx_queue, uint32_t access_address,
                                uint8_t crc_init_0, uint8_t crc_init_1,
