#include <stddef.h>
#include <stdint.h>

#include "systick.h"

#include "sam4_gpio.h"

#include "workqueue.h"

#include "led.h"

void led_worker(void *arg)
{
    led_t *led = (led_t *)arg;
    uint32_t ticks = 0;

    switch (led->state)
    {
        case LED_STATE_BEACON:
            ticks = (LED_BEACON_INTERVAL_mS * SYSTICK_FREQ) / 1000;
            if (led->flags & LED_FLAGS_ON)
            {
                led->flags &= ~LED_FLAGS_ON;
            }
            else
            {
                led->flags |= LED_FLAGS_ON;
            }
            break;

        case LED_STATE_OFF:
            led->flags &= ~LED_FLAGS_ON;
            break;

        case LED_STATE_ON:
            led->flags |= LED_FLAGS_ON;
            break;

        case LED_STATE_TRAFFIC:
            ticks = (LED_TRAFFIC_INTERVAL_mS * SYSTICK_FREQ) / 1000;
            if (led->flags & LED_FLAGS_ON)
            {
                led->flags &= ~LED_FLAGS_ON;
            }
            else
            {
                led->flags |= LED_FLAGS_ON;
            }
            break;
    }

    if (led->flags & LED_FLAGS_ON)
    {
        GPIO_SET_HIGH(led->gpio, led->pin);
    }
    else
    {
        GPIO_SET_LOW(led->gpio, led->pin);
    }

    if (ticks)
    {
        workqueue_add(&led->wq, ticks);
    }
}

