    }
    inline u32 getGreen(u32 Color)
    {
        return (Color >> 8) & 0xFF;
    }
    inline u32 getBlue(u32 Color)
    {
        return Color & 0xFF;
    }

    inline u32 getColor(u32 Red, u32 Green, u32 Blue, u32 Alpha)
    {
        return ((Alpha & 0xFF) << 24) | ((Red & 0xFF) << 16) | ((Green & 0xFF) << 8) | (Blue & 0xFF);
    }


    class color
    {

    public:

        color() :
