    field[i++] = 0.0;
    // star1 B: (2,2)
    field[i++] = 2.0;
    field[i++] = 2.0;
    // star2
    field[i++] = -1.0;
    field[i++] = 3.0;
    // star3
    field[i++] = 0.5;
    field[i++] = 1.5;
    // star4
    field[i++] = 1.0;
    field[i++] = 1.0;
    // star5
    field[i++] = 1.5;
    field[i++] = 0.5;
    // star6
    field[i++] = 3.0;
    field[i++] = -1.0;

    N = i/2;
    starxy = starxy_new(N, FALSE, FALSE);
    for (i=0; i<N; i++) {
        starxy_setx(starxy, i, field[i*2+0]);
        starxy_sety(starxy, i, field[i*2+1]);
    }
	return starxy;
}

void test1() {
	int i;
    solver_t* solver;
    index_t index;
    starxy_t* starxy;
    int wanted[][4] = { { 0,1,3,4 },
                         { 0,2,3,4 },
                         { 1,2,3,4 },
                         { 2,5,0,1 },
                         { 2,5,0,3 },
                         { 2,5,0,4 },
                         { 2,5,1,3 },
                         { 2,5,1,4 },
                         { 2,5,3,4 },
                         { 0,1,3,5 },
                         { 0,1,4,5 },
                         { 0,6,4,5 },
                         { 1,6,4,5 },
                         { 2,6,0,1 },
                         { 2,6,0,3 },
                         { 2,6,0,4 },
                         { 2,6,0,5 },
                         { 2,6,1,3 },
                         { 2,6,1,4 },
                         { 2,6,1,5 },
                         { 2,6,3,4 },
                         { 2,6,3,5 },
                         { 2,6,4,5 },
                         { 3,6,0,1 },
                         { 3,6,0,4 },
                         { 3,6,0,5 },
                         { 3,6,1,4 },
                         { 3,6,1,5 },
                         { 3,6,4,5 },
    };

	starxy = field1();

    quadlist = bl_new(16, 4*sizeof(uint));

    solver = solver_new();

    memset(&index, 0, sizeof(index_t));
    index.index_scale_lower = 1;
    index.index_scale_upper = 10;
	index.dimquads = 4;

    solver->funits_lower = 0.1;
    solver->funits_upper = 10;

    solver_add_index(solver, &index);
    solver_set_field(solver, starxy);
    solver_preprocess_field(solver);

    solver_run(solver);

    solver_free_field(solver);
    solver_free(solver);

    //
    assert(bl_size(quadlist) == (sizeof(wanted) / (4*sizeof(uint))));
    for (i=0; i<bl_size(quadlist); i++) {
        assert(compare_quad(bl_access(quadlist, i), wanted[i]) == 0);
    }

    bl_free(quadlist);
}

void test2() {
	int i;
    solver_t* solver;
    index_t index;
    starxy_t* starxy;
    int wanted[][3] = { { 0, 1, 3 },
						{ 0, 1, 4 },
