	if (n < 0)
	{
	    printf("x86mainStartFirstThread: thread number fail");
        die();
	}


	switch (n){

		case 1:
		    Thread = IdleThread; 
		    break;

		case 2:
		    Thread = ShellThread;
			break;

		case 3:
