        dispatcherReadyList[i] = (unsigned long) Thread;
    }


    IncrementDispatcherCount (SELECT_IDLE_COUNT);


    //Set cr3 and flush TLB.
    mainSetCr3 ( (unsigned long) Thread->DirectoryPA );
    asm ("movl %cr3, %eax");
    asm ("movl %eax, %cr3");


    /* turn_task_switch_on:
     * + Creates a vector for timer irq, IRQ0.
