	//init
    if (n == 1 )
    {		

        asm volatile (" cli \n"
                  " mov $0x23, %ax  \n"
                  " mov %ax, %ds  \n"
                  " mov %ax, %es  \n"
                  " mov %ax, %fs  \n"
