/*            EDGEGEN GREEDY_TOUR                                           */
/*                    -find a greedy tour                                   */
/*            EDGEGEN BORUVKA_TOUR                                          */
/*                    -find a Boruvka tour                                  */
/*            EDGEGEN QBORUVKA_TOUR                                         */
/*                    -find a quick Boruvka tour                            */
/*            EDGEGEN NN_TOUR #                                             */
/*                    -find # nearest-neighbor tours                        */
/*            EDGEGEN RANDOM_TOUR #                                         */
