}

static int
xputc(int c)
{
	return (fputc(c, stdout));
}

static void
xputs(const char *s)
{
	tputs(s, 1, xputc);
}

static void
cmov(int x, int y)
{
	char *p; 

	p = tiparm(cursor_address, y - 1, x - 1);
	if (p) {
		xputs(p);
		cury = y;
		curx = x;
	}
}

static void
nocmov(int x, int y)
{
	if (cury > y) {
		if (cursor_up) {
			while (cury > y) {	/* Go up. */
				xputs(cursor_up);
				cury--;
			}
		} else if (cursor_address) {
			cmov(x, y);
		} else if (cursor_home) {
			home();
			curs(x, y);
		}		/* else impossible("..."); */
	} else if (cury < y) {
		if (cursor_address) {
			cmov(x, y);
#if 0
		} else if (XD) {
			while (cury < y) {
				xputs(XD);
				cury++;
			}
#endif
		} else {
			while (cury < y) {
				xputc('\n');
				curx = 1;
				cury++;
			}
		}
	}
	if (curx < x) {		/* Go to the right. */
		if (!cursor_right)
			cmov(x, y);
		else		/* bah */
			/* should instead print what is there already */
			while (curx < x) {
				xputs(cursor_right);
				curx++;
			}
	} else if (curx > x) {
		while (curx > x)
			backsp();
	}
}

/*
 * Cursor movements
 *
 * x,y not xchar: perhaps xchar is unsigned and
 * curx-x would be unsigned as well
 */
void
curs(int x, int y)
{

	if (y == cury && x == curx)
		return;
	if (!cursor_right && (curx != x || x <= 3)) { /* Extremely primitive */
		cmov(x, y);	/* bunker!wtm */
		return;
	}
	if (abs(cury - y) <= 3 && abs(curx - x) <= 3)
		nocmov(x, y);
	else if ((x <= 3 && abs(cury - y) <= 3) ||
	    (!cursor_address && x < abs(curx - x)))
	{
		(void) putchar('\r');
		curx = 1;
		nocmov(x, y);
	} else if (!cursor_address) {
		nocmov(x, y);
	} else
		cmov(x, y);
}

void
cl_end(void)
{
	if (clr_eol)
		xputs(clr_eol);
	else {			/* no-CE fix - free after <NAME> */
		/*
		 * this looks terrible, especially on a slow terminal but is
		 * better than nothing
		 */
		int cx = curx, cy = cury;

		while (curx < COLNO) {
			xputc(' ');
			curx++;
		}
		curs(cx, cy);
	}
}

void
clearscreen(void)
{
	xputs(clear_screen);
	curx = cury = 1;
}

void
home(void)
{
	char *out;

	if (cursor_home)
		xputs(cursor_home);
	else if ((cursor_address) && (out = tiparm(cursor_address, 0, 0)))
		xputs(out);
	else
		curs(1, 1);	/* using UP ... */
	curx = cury = 1;
}

void
standoutbeg(void)
{
	if (enter_standout_mode && exit_standout_mode && !magic_cookie_glitch)
		xputs(enter_standout_mode);
}

void
standoutend(void)
{
	if (exit_standout_mode && enter_standout_mode && !magic_cookie_glitch)
		xputs(exit_standout_mode);
}

void
backsp(void)
{
	if (cursor_left)
		xputs(cursor_left);
	else
		(void) putchar('\b');
	curx--;
}

void
sound_bell(void)
{
	(void) putchar('\007');	/* curx does not change */
	(void) fflush(stdout);
}

void
delay_output(void)
{

	/* delay 50 ms - could also use a 'nap'-system call */
	  /* or the usleep call like this :-) */
	usleep(50000);
}

void
cl_eos(void)
{				/* free after <NAME> *//* must only be
				 * called with curx = 1 */

	if (clr_eos)
		xputs(clr_eos);
	else {
		int             cx = curx, cy = cury;
		while (cury <= LI - 2) {
			cl_end();
			xputc('\n');
			curx = 1;
			cury++;
		}
		cl_end();
		curs(cx, cy);
	}
}

