#include <fcntl.h>
#include <string.h>
#include <unistd.h>

#define ROW0 24
#define ROW1 27
#define ROW2 25
#define ROW3 28
#define ROW4 29

#define COL0 1
#define COL1 2
#define COL2 3
#define COL3 4
#define COL4 5
#define COL5 6

#define COL6 23
#define COL7 26
#define COL8 22
#define COL9 21
#define COL10 30
#define COL11 31

#define COLUMNS 12
#define ROWS 5

unsigned char keyStat[COLUMNS][ROWS];
unsigned char keyNewStat[COLUMNS][ROWS];

int keyMap[ROWS][COLUMNS] = {
	{0, KEY_1, KEY_2, KEY_3, KEY_4, KEY_5, KEY_6, KEY_7, KEY_8, KEY_9, KEY_0, KEY_BACKSPACE},
	{KEY_TAB, KEY_Q, KEY_W, KEY_E, KEY_R, KEY_T, KEY_Y, KEY_U, KEY_I, KEY_O, KEY_P, KEY_BACKSLASH},
