void free_grid (void)
{
  if (!grid)
    return;
  free_boundaries();
  Tree * q = tree;
  free (q->leaves.p);
  free (q->faces.p);
  free (q->vertices.p);
  free (q->refined.p);
  /* low-level memory management */
  /* the root level is allocated differently */
  Layer * L = q->L[0];
#if dimension == 1
  for (int i = Period.x*GHOSTS; i < L->len - Period.x*GHOSTS; i++)
    free (L->m[i]);
#elif dimension == 2
  for (int i = Period.x*GHOSTS; i < L->len - Period.x*GHOSTS; i++) {
    for (int j = Period.y*GHOSTS; j < L->len - Period.y*GHOSTS; j++)
      free (L->m[i][j]);
    free (L->m[i]);
  }
  /* all other levels */
  for (int l = 1; l <= depth(); l++) {
    Layer * L = q->L[l];
    for (int i = Period.x*GHOSTS; i < L->len - Period.x*GHOSTS; i++)
      free (L->m[i]);
  }
#else // dimension == 3
  for (int i = Period.x*GHOSTS; i < L->len - Period.x*GHOSTS; i++) {
    for (int j = Period.y*GHOSTS; j < L->len - Period.y*GHOSTS; j++) {
      for (int k = Period.z*GHOSTS; k < L->len - Period.z*GHOSTS; k++)
	free (L->m[i][j][k]);
      free (L->m[i][j]);
    }
    free (L->m[i]);
  }
  /* all other levels */
  for (int l = 1; l <= depth(); l++) {
    Layer * L = q->L[l];
    for (int i = Period.x*GHOSTS; i < L->len - Period.x*GHOSTS; i++)
      if (L->m[i]) {
	for (int j = Period.y*GHOSTS; j < L->len - Period.y*GHOSTS; j++)
	  if (L->m[i][j])
	    free (L->m[i][j]);
	free (L->m[i]);
      }
  }
#endif // dimension == 3
  for (int l = 0; l <= depth(); l++)
    destroy_layer (q->L[l]);
  q->L = &(q->L[-1]);
  free (q->L);
  free_cache (q->active);
  free_cache (q->prolongation);
  free_cache (q->boundary);
  free_cache (q->restriction);
  free (q);
  grid = NULL;
}

