    BufferedFileCommon& operator=(const BufferedFileCommon&) = delete;
};

class BufferedFile {
    BufferedFileCommon* common = nullptr;

    mutable off_t pos = 0;
    bool read_only = true;
    mutable size_t buf_end = 0;
    mutable char buf[4096];

    const int FORCED_CLOSE = -2;

