static __always_inline __maybe_unused bool
__revalidate_data(struct __ctx_buff *ctx, void **data_, void **data_end_,
		  void **l3, const __u32 l3_len, const bool pull)
{
	const __u32 tot_len = ETH_HLEN + l3_len;
