/*
 * _pss_glob(3) -- a subset of the one defined in POSIX 1003.2.
 *
 * Optional extra services, controlled by flags not defined by POSIX:
 *
 * GLOB_MAGCHAR:
 *	Set in gl_flags if pattern contained a globbing character.
 */


#include <config.h>
#include <glib.h>

#include <mono/metadata/exception.h>
#include <mono/metadata/file-io.h>
#include <mono/metadata/file-io-pss.h>
#include <mono/metadata/file-io-native.h>

#include "pssdef.h"

#include "file-io-pss-glob.h"

#ifndef PATH_MAX
#define PATH_MAX 1024
#endif

#define	EOS		'\0'
#define	NOT		'!'
#define	QUESTION	'?'
#define	QUOTE		'\\'
#define	STAR		'*'

#define	M_QUOTE		0x8000
#define	M_PROTECT	0x4000
#define	M_MASK		0xffff
#define	M_ASCII		0x00ff

typedef u_short Char;

#define	CHAR(c)		((gchar)((c)&M_ASCII))
#define	META(c)		((gchar)((c)|M_QUOTE))
#define	M_ALL		META('*')
#define	M_ONE		META('?')
#define	ismeta(c)	(((c)&M_QUOTE) != 0)

static int	 g_Ctoc(const gchar *, char *, u_int);
static int	 glob0(ScePssHandle dir, const Char *, pss_glob_t *, gboolean, gboolean, scePssDirectoryReadFunc);
static int	 glob1(ScePssHandle dir, Char *, Char *, pss_glob_t *, size_t *, gboolean, gboolean, scePssDirectoryReadFunc);
static int	 glob3(ScePssHandle dir, Char *, Char *, pss_glob_t *, size_t *, gboolean, gboolean, scePssDirectoryReadFunc);
static int	 globextend(const gchar *, pss_glob_t *, size_t *);
static int	 match(Char *, Char *, Char *, gboolean);
#ifdef DEBUG
static void	 qprintf(const char *, Char *);
#endif

#if !HAVE_STRNLEN
/* like strlen, but returns max_len if the string is longer */
static int
strnlen (const char *str, int max_len)
{
  int len = strlen (str);
  return len > max_len ? max_len : len;
}
#endif

int
_pss_glob(ScePssHandle dir, const char *pattern, int flags, pss_glob_t *pglob, scePssDirectoryReadFunc scePssDirectoryRead)
{
	const u_char *patnext;
	int c;
	Char *bufnext, *bufend, patbuf[PATH_MAX];

	if (strnlen(pattern, PATH_MAX) == PATH_MAX)
		return(PSS_GLOB_NOMATCH);

	patnext = (u_char *) pattern;
	if (!(flags & PSS_GLOB_APPEND)) {
		pglob->gl_pathc = 0;
		pglob->gl_pathv = NULL;
		pglob->gl_offs = 0;
	}
	pglob->gl_flags = flags & ~PSS_GLOB_MAGCHAR;

	bufnext = patbuf;
	bufend = bufnext + PATH_MAX - 1;

	/* Protect the quoted characters. */
	while (bufnext < bufend && (c = *patnext++) != EOS)
		if (c == QUOTE) {
			if ((c = *patnext++) == EOS) {
				c = QUOTE;
				--patnext;
			}
			*bufnext++ = c | M_PROTECT;
		} else
			*bufnext++ = c;

	*bufnext = EOS;

	return glob0(dir, patbuf, pglob, flags & PSS_GLOB_IGNORECASE, flags & PSS_GLOB_UNIQUE, scePssDirectoryRead);
}

/*
 * The main glob() routine: compiles the pattern (optionally processing
 * quotes), calls glob1() to do the real pattern matching, and finally
 * sorts the list (unless unsorted operation is requested).  Returns 0
 * if things went well, nonzero if errors occurred.  It is not an error
 * to find no matches.
 */
static int
glob0(ScePssHandle dir, const Char *pattern, pss_glob_t *pglob, gboolean ignorecase,	gboolean unique, scePssDirectoryReadFunc scePssDirectoryRead)
{
	const Char *qpatnext;
	int c, err, oldpathc;
	Char *bufnext, patbuf[PATH_MAX];
	size_t limit = 0;

	qpatnext = pattern;
	oldpathc = pglob->gl_pathc;
	bufnext = patbuf;

	/* We don't need to check for buffer overflow any more. */
	while ((c = *qpatnext++) != EOS) {
		switch (c) {
		case QUESTION:
			pglob->gl_flags |= PSS_GLOB_MAGCHAR;
			*bufnext++ = M_ONE;
			break;
		case STAR:
			pglob->gl_flags |= PSS_GLOB_MAGCHAR;
			/* collapse adjacent stars to one,
			 * to avoid exponential behavior
			 */
			if (bufnext == patbuf || bufnext[-1] != M_ALL)
				*bufnext++ = M_ALL;
			break;
		default:
			*bufnext++ = CHAR(c);
			break;
		}
	}
	*bufnext = EOS;
#ifdef DEBUG
	qprintf("glob0:", patbuf);
#endif

	if ((err = glob1(dir, patbuf, bufnext, pglob, &limit,
			 ignorecase, unique, scePssDirectoryRead)) != 0)
		return(err);

	if (pglob->gl_pathc == oldpathc) {
		return(PSS_GLOB_NOMATCH);
	}

	return(0);
}

static int
glob1(ScePssHandle dir, Char *pattern, Char *pattern_last, pss_glob_t *pglob,
      size_t *limitp, gboolean ignorecase, gboolean unique, scePssDirectoryReadFunc scePssDirectoryRead)
{
	/* A null pathname is invalid -- POSIX 1003.1 sect. 2.4. */
	if (*pattern == EOS)
		return(0);
	return(glob3(dir, pattern, pattern_last, pglob, limitp, ignorecase,
		     unique, scePssDirectoryRead));
}

static gboolean contains (pss_glob_t *pglob, const gchar *name)
{
	int i;
	char **pp;

	if (pglob->gl_pathv != NULL) {
		pp = pglob->gl_pathv + pglob->gl_offs;
		for (i = pglob->gl_pathc; i--; ++pp) {
			if (*pp) {
				if (!strcmp (*pp, name)) {
					return(TRUE);
				}
			}
		}
	}

	return(FALSE);
}

static int
glob3(ScePssHandle dir, Char *pattern, Char *pattern_last, pss_glob_t *pglob,
      size_t *limitp, gboolean ignorecase, gboolean unique, scePssDirectoryReadFunc scePssDirectoryRead)
{
	ScePssFileInformation_t info;
	ScePssResult res;

	while ((res = scePssDirectoryRead (dir, &info)) == SCE_PSS_ERROR_NO_ERROR) {

		Char* buf = (Char*)malloc(sizeof(Char) * (strlen(info.szName) + 1));
		Char* bufnext;
		Char* bufend;

		char c;
		char* namenext;

		bufnext = buf;
		bufend = buf + strlen(info.szName);

		namenext = info.szName;

		/* Protect the quoted characters. */
		while (bufnext < bufend && (c = *namenext++) != EOS)
			if (c == QUOTE) {
				if ((c = *namenext++) == EOS) {
					c = QUOTE;
					--namenext;
				}
				*bufnext++ = c | M_PROTECT;
			} else
				*bufnext++ = c;

		*bufnext = EOS;

		// XXX
		if (!match (buf, pattern, pattern_last, ignorecase)) {
			free(buf);
			continue;
		}
		free (buf);
		if (!unique ||
			!contains (pglob, info.szName)) {
				globextend (info.szName, pglob, limitp);
		}
	}

	return(0);
}


/*
 * Extend the gl_pathv member of a pss_glob_t structure to accommodate a new item,
 * add the new item, and update gl_pathc.
 *
 * This assumes the BSD realloc, which only copies the block when its size
 * crosses a power-of-two boundary; for v7 realloc, this would cause quadratic
 * behavior.
 *
 * Return 0 if new item added, error code if memory couldn't be allocated.
 *
 * Invariant of the pss_glob_t structure:
 *	Either gl_pathc is zero and gl_pathv is NULL; or gl_pathc > 0 and
 *	gl_pathv points to (gl_offs + gl_pathc + 1) items.
 */
static int
globextend(const gchar *path, pss_glob_t *pglob, size_t *limitp)
{
	char **pathv;
	int i;
	u_int newsize, len;
	char *copy;
	const gchar *p;

	newsize = sizeof(*pathv) * (2 + pglob->gl_pathc + pglob->gl_offs);
	pathv = (char**)(pglob->gl_pathv ? realloc((char *)pglob->gl_pathv, newsize) :
					 malloc(newsize));
	if (pathv == NULL) {
		if (pglob->gl_pathv) {
			free(pglob->gl_pathv);
			pglob->gl_pathv = NULL;
		}
		return(PSS_GLOB_NOSPACE);
	}

	if (pglob->gl_pathv == NULL && pglob->gl_offs > 0) {
		/* first time around -- clear initial gl_offs items */
		pathv += pglob->gl_offs;
		for (i = pglob->gl_offs; --i >= 0; )
			*--pathv = NULL;
	}
	pglob->gl_pathv = pathv;

	for (p = path; *p++;)
		;
	len = (size_t)(p - path);
	*limitp += len;
	if ((copy = (char*)malloc(len)) != NULL) {
		if (g_Ctoc(path, copy, len)) {
			free(copy);
			return(PSS_GLOB_NOSPACE);
		}
		pathv[pglob->gl_offs + pglob->gl_pathc++] = copy;
	}
	pathv[pglob->gl_offs + pglob->gl_pathc] = NULL;

#if 0
	/* Broken on opensuse 11 */
	if ((pglob->gl_flags & PSS_GLOB_LIMIT) &&
	    newsize + *limitp >= ARG_MAX) {
		errno = 0;
		return(PSS_GLOB_NOSPACE);
	}
#endif

	return(copy == NULL ? PSS_GLOB_NOSPACE : 0);
}


/*
 * pattern matching function for filenames.  Each occurrence of the *
 * pattern causes a recursion level.
 */
static int
match(Char *name, Char *pat, Char *patend, gboolean ignorecase)
{
	gchar c;

	while (pat < patend) {
		c = *pat++;
		switch (c & M_MASK) {
		case M_ALL:
			if (pat == patend)
				return(1);
			while (pat < patend && (*pat & M_MASK) == M_ALL)
				pat++;	/* eat consecutive '*' */
			do {
				if (match(name, pat, patend, ignorecase))
					return(1);
			} while (*name++ != EOS);
			return(0);
		case M_ONE:
			if (*name++ == EOS)
				return(0);
			break;
		default:
			if (ignorecase) {
				gchar char_name = (gchar)CHAR(*name++);
				gchar char_c = (gchar)CHAR(c);
				if (g_ascii_tolower (char_name) != g_ascii_tolower (char_c))
					return(0);
			} else {
				if (*name++ != c)
					return(0);
			}

			break;
		}
	}
	return(*name == EOS);
}

/* Free allocated data belonging to a pss_glob_t structure. */
void
_pss_globfree(pss_glob_t *pglob)
{
	int i;
	char **pp;

	if (pglob->gl_pathv != NULL) {
		pp = pglob->gl_pathv + pglob->gl_offs;
		for (i = pglob->gl_pathc; i--; ++pp)
			if (*pp)
				free(*pp);
		free(pglob->gl_pathv);
		pglob->gl_pathv = NULL;
	}
}

static int
g_Ctoc(const gchar *str, char *buf, u_int len)
{

	while (len--) {
		if ((*buf++ = *str++) == EOS)
			return (0);
	}
	return (1);
}

#ifdef DEBUG
static void
qprintf(const char *str, Char *s)
{
	Char *p;

	(void)printf("%s:\n", str);
	for (p = s; *p; p++)
		(void)printf("%c", CHAR(*p));
	(void)printf("\n");
	for (p = s; *p; p++)
		(void)printf("%c", *p & M_PROTECT ? '"' : ' ');
	(void)printf("\n");
	for (p = s; *p; p++)
		(void)printf("%c", ismeta(*p) ? '_' : ' ');
	(void)printf("\n");
}
#endif

