png_uint_32 png_get_uint_31(png_const_bytep buf) {
  png_uint_32 uval = png_get_uint_32(buf);
  if (uval > PNG_UINT_31_MAX) {
    exit(0);
  };
  return (uval);
}

int main(int argc, char** argv) {
  if (argc < 2) return 0;

  FILE* fp;

  fp = fopen(argv[1], "rb");

  if (!fp) {
    printf("st err\n");
    return 0;
  }
  png_byte buf[13];
  fread(buf, 13, 1, fp);
  fclose(fp);

  // png_handle_IHDR
  png_uint_32 width, height;
  png_byte bit_depth, color_type, compression_type, filter_type;
  png_byte interlaced, channels;
  width = png_get_uint_31(buf);
  height = png_get_uint_31(buf + 4);
  bit_depth = buf[8];
  color_type = buf[9];
  compression_type = buf[10];
  filter_type = buf[11];
  interlaced = buf[12];

  uint32_t max_pixel_depth = bit_depth;
  if (max_pixel_depth < 4) {
    return 0;
  }

  uint32_t row_bytes = ((width + 7) & ~((png_uint_32)7));
  row_bytes = PNG_ROWBYTES(max_pixel_depth, row_bytes) + 1 +
              ((max_pixel_depth + 7) >> 3U);
  size_t row_bytes_check = row_bytes & ~((size_t)7);
  /* The input width resulted in an integer overflow, which could
   * later cause a heap buffer overflow due to a bad allocation size
   */
  if (row_bytes_check < ((width + 7) & ~((png_uint_32)7))) {
    abort();
  }
  return 0;
}

