                         {
                            //p_seq->is_play_to_end = 1;
                            return 0;
                         }
                    }
                    else
                    {
                         errorcnt = 0;
                    }

		     }
                   if(demux->audio->eof ||demux->video->eof)
                   {
                     if(pkt.data){
                        av_free_packet(&pkt);
                     }
                     OS_PRINTF("audio->eof %d video->eof %d\n",
                        demux->audio->eof ,demux->video->eof);
