		// subtitle
		ds=demux->sub;
		sub_utf8=1;
	} else {
		av_free_packet(&pkt);
		return 1;
	}

	if(pkt.destruct == av_destruct_packet && !CONFIG_MEMALIGN_HACK){
		dp=new_demux_packet(0);
		dp->len=pkt.size;
		dp->buffer=pkt.data;
		pkt.destruct= NULL;
	}else{
		dp=new_demux_packet(pkt.size);
		memcpy(dp->buffer, pkt.data, pkt.size);
		av_free_packet(&pkt);
