inline ParametricLine::ParametricLine(const PrecXY& p1, const PrecXY& p2) {
    a = p2.y - p1.y;
    b = p1.x - p2.x;
    c = p2.x*p1.y - p1.x*p2.y;
    if(a == 0 && b == 0) {
