	virtual int getplanid(){return 3;};
	virtual void getlabel(char *buffer){strcpy(buffer,"Plan:Sling Direct");};
	virtual void getviewname(char *buffer){strcpy(buffer,"View:Sling Direct");};

};

class encounterplan:public plan
{
private:
