int Volpex_msg_performance_free(Volpex_proc *tproc)
{
  Volpex_msg_perf *tnode = NULL;

  while (tproc->msgperf!=NULL){
    tnode = tproc->msgperf;
    if(tnode->pos != MSGPERF){
      tproc->msgperf = tproc->msgperf->fwd;
      free(tnode);
    }
