class PFMuonAlgo {

  typedef reco::Muon::MuonTrackTypePair MuonTrackTypePair;
  typedef reco::Muon::MuonTrackType  MuonTrackType;

 public:

  /// constructor
  PFMuonAlgo();

  void setParameters(const edm::ParameterSet&);



