                X1 = n == 0      ?  A.i       %A.mb   : 0;
                X2 = n == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                X = X2 - X1;

                Y1 = n == 0      ?  A.j       %A.nb   : 0;
                Y2 = n == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;
                Y = Y2 - Y1;

                ldan = BLKLDD(A, n);
                QUARK_CORE_dtrasm_f1(
                    plasma->quark, &task_flags,
                    PlasmaRowwise, uplo, diag, X, Y,
                    A(n, n, X1, Y1, ldan), ldan, ldan*X,
                    &(lwork[n*A.mb+1]), A.mb,
                    lwork, A.m+1);

                for(m = n+1; m < A.mt; m++) {
                    X = m == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                    ldam = BLKLDD(A, m);

                    QUARK_CORE_dasum_f1(
                        plasma->quark, &task_flags,
                        PlasmaRowwise, PlasmaUpperLower,
                        X, Y,
                        A(m, n, 0, Y1, ldam), ldam, ldam*Y,
                        &(lwork[m*A.mb+1]), A.mb,
                        lwork, A.m+1);
                }
            }
        }
        /*
         *  PlasmaUpper
         */
        else {
            for(m = 0; m < minMNT; m++) {
                X1 = m == 0      ?  A.i       %A.mb   : 0;
                X2 = m == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                X = X2 - X1;

                Y1 = m == 0      ?  A.j       %A.nb   : 0;
                Y2 = m == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;
                Y = Y2 - Y1;

                ldam = BLKLDD(A, m);
                QUARK_CORE_dtrasm_f1(
                    plasma->quark, &task_flags,
                    PlasmaRowwise, uplo, diag, X, Y,
                    A(m, m, X1, Y1, ldam), ldam, ldam*X,
                    &(lwork[m*A.mb+1]), A.mb,
                    lwork, A.m+1);

                for(n = m+1; n < A.nt; n++) {
                    Y = n == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;
                    QUARK_CORE_dasum_f1(
                        plasma->quark, &task_flags,
                        PlasmaRowwise, PlasmaUpperLower,
                        X, Y,
                        A(m, n, X1, 0, ldam), ldam, ldam*Y,
                        &(lwork[m*A.mb+1]), A.mb,
                        lwork, A.m+1);
                }
            }
        }
        QUARK_CORE_dlange(
            plasma->quark, &task_flags,
            PlasmaMaxNorm, A.m+1, 1,
            lwork, 1, A.m+1,
            0, result);

        QUARK_CORE_free(plasma->quark, &task_flags, lwork, (A.m+1)*sizeof(double));
