        if (uplo == PlasmaLower) {
            for(n = 0; n < minMNT; n++) {
                X1 = n == 0      ?  A.i       %A.mb   : 0;
                X2 = n == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                X = X2 - X1;

                Y1 = n == 0      ?  A.j       %A.nb   : 0;
                Y2 = n == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;
                Y = Y2 - Y1;

                ldan = BLKLDD(A, n);

                k++; nbworker++;
                QUARK_CORE_dtrssq_f1(
                    plasma->quark, &task_flags,
                    uplo, diag, X, Y,
                    A(n, n, X1, Y1, ldan), ldan,
                    lwork + 2*k,
                    lwork + 2*k + 1,
                    lwork, szeW, OUTPUT | GATHERV );
                k = k % PLASMA_SIZE;

                for(m = n+1; m < A.mt; m++) {
                    X = m == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                    ldam = BLKLDD(A, m);

                    k++; nbworker++;
                    QUARK_CORE_dgessq_f1(
                        plasma->quark, &task_flags,
                        X, Y,
                        A(m, n, 0, Y1, ldam), ldam,
                        lwork + 2*k,
                        lwork + 2*k + 1,
                        lwork, szeW, OUTPUT | GATHERV );

                    k = k % PLASMA_SIZE;
                }
            }
        }
        /*
         *  PlasmaUpper
         */
        else {
            for(m = 0; m < minMNT; m++) {
                X1 = m == 0      ?  A.i       %A.mb   : 0;
                X2 = m == A.mt-1 ? (A.i+A.m-1)%A.mb+1 : A.mb;
                X = X2 - X1;

                Y1 = m == 0      ?  A.j       %A.nb   : 0;
                Y2 = m == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;
                Y = Y2 - Y1;

                ldam = BLKLDD(A, m);

                k++; nbworker++;
                QUARK_CORE_dtrssq_f1(
                    plasma->quark, &task_flags,
                    uplo, diag, X, Y,
                    A(m, m, X1, Y1, ldam), ldam,
                    lwork + 2*k,
                    lwork + 2*k + 1,
                    lwork, szeW, OUTPUT | GATHERV );
                k = k % PLASMA_SIZE;

                for(n = m+1; n < A.nt; n++) {
                    Y = n == A.nt-1 ? (A.j+A.n-1)%A.nb+1 : A.nb;

                    k++; nbworker++;
                    QUARK_CORE_dgessq_f1(
                        plasma->quark, &task_flags,
                        X, Y,
                        A(m, n, X1, 0, ldam), ldam,
                        lwork + 2*k,
                        lwork + 2*k + 1,
                        lwork, szeW, OUTPUT | GATHERV );

                    k = k % PLASMA_SIZE;
                }
            }
        }
        QUARK_CORE_dplssq(
            plasma->quark, &task_flags,
            min(nbworker, PLASMA_SIZE+1), lwork, result );

        QUARK_CORE_free(plasma->quark, &task_flags, lwork, szeW*sizeof(double));
    default:;
    }
}

