            dfacc = 1;
        }
        else
        {
            RZA_IO_RegWrite_16(&USB201.D1FBCFG,
                                0,
                                USB_DnFBCFG_DFACC_SHIFT,
                                USB_DnFBCFG_DFACC);
            RZA_IO_RegWrite_16(&USB201.D1FBCFG,
