static INLINE uint32 
get_rand(uint32 *rand_seed, uint32 *rand_carry) {

	/* A multiply-with-carry generator by <NAME>.
	   The period is about 2^63. */

	#define RAND_MULT 2131995753

	uint64 temp;

	temp = (uint64)(*rand_seed) * 
		       (uint64)RAND_MULT + 
