  StaticContent common_{"/common", "app"};
  StaticContent app_{"/kb/app", "sling/nlp/kb/app"};

  // Document tokenizer and lexer.
  DocumentTokenizer tokenizer_;
  DocumentLexer lexer_{&tokenizer_};

  // Symbols.
  Names names_;
