#include <stdio.h>

enum State {
    IN,
    OUT
};

int main()
{
    int nwords = 0; /* number of words */
    int state = OUT; /* in or out word */
    int c;

    while ((c = getchar()) != EOF) {

        if (c == '\n' || c == ' ' || c == '\t') {
            state = OUT;
        } else if (state == OUT) {
            ++nwords;
            state = IN;
        }
    }

    printf("%d\n", nwords);

    return 0;
}

