/*_RB_ Definitions require comments to say what and why. */
#define sdSIGNATURE 0x41404342

/*_RB_ IO manager memory size needs to be configurable. */
#define sdIOMAN_MEM_SIZE	4096
#define sdHUNDRED_64_BIT	100ULL

/*-----------------------------------------------------------*/

