/*
 * Note - the following defines have been moved to 'wd33c93.h':
 *
 *    PROC_INTERFACE
 *    PROC_STATISTICS
 *    SYNC_DEBUG
 *    DEBUGGING_ON
 *    DEBUG_DEFAULTS
 *
