                                         struct RFilist_head *from,
                                         const char *errstr);
i_INLINE_INS void i_rf_ilist_prepend_list(struct RFilist_head *to,
                                        struct RFilist_head *from,
                                        const char *errstr);
i_INLINE_INS void *rf_ilist_node_to_off(const struct RFilist_node *node, size_t off);
