            case LimitSwitchNormal_NormallyClosed : return "LimitSwitchNormal_NormallyClosed";
            case LimitSwitchNormal_Disabled : return "LimitSwitchNormal_Disabled";
            default : return "InvalidValue";
        }

    }

};
} // namespace motorcontrol
} // namespace phoenix
