void    ft_print_comb(void)
{
    int num1;
    int num2;
    int num3;

    num1 = 0;
    while (num1 <= 7)
    {
        num2 = num1 + 1;
        while (num2 <= 8)
        {
            num3 = num2 + 1;
            while (num3 <= 9)
            {
