		if ((c3 & 0xC0) != 0x80) return -1;			// Illegal subsequent byte.
		if (c1 == 0xE0 && c2 < 0xA0) return -1;		// Illegal overlong encoding.
		return (c1 << 12) + (c2 << 6) + c3 - 0xE2080;
	}
