#include <libgen.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

static pid_t daemon_pid;

static void
daemon_stop(void)
{
    if (daemon_pid == 0)
        return;
    kill(daemon_pid, SIGTERM);
    waitpid(daemon_pid, NULL, 0);
    daemon_pid = 0;
}

static krb5_boolean
daemon_start(int argc, const char **argv)
{
    int fds[2];
    char buf[1];

    if (argc != 3 || argv == NULL)
        return FALSE;

    if (daemon_pid != 0)
        return TRUE;

    if (pipe(fds) != 0)
        return FALSE;

    /* Start the child process with the write end of the pipe as stdout. */
    daemon_pid = fork();
    if (daemon_pid == 0) {
        dup2(fds[1], STDOUT_FILENO);
        close(fds[0]);
        close(fds[1]);
        exit(execlp(argv[1], argv[1], argv[2], NULL));
    }
    close(fds[1]);

    /* The child will write a sentinel character when it is listening. */
    if (read(fds[0], buf, 1) != 1 || *buf != '~')
        return FALSE;
    close(fds[0]);

    atexit(daemon_stop);
    return TRUE;
}

#endif /* T_DAEMON_H_ */

