struct spinlock tickslock;
uint ticks;

void timerinit() {
    initlock(&tickslock, "time");
    #ifdef DEBUG
    printf("timerinit\n");
    #endif
}

void
set_next_timeout() {
    // There is a very strange bug,
    // if comment the `printf` line below
    // the timer will not work.

    // this bug seems to disappear automatically
//     printf("");
    sbi_set_timer(r_time() + INTERVAL);
}

void timer_tick() {
    acquire(&tickslock);
    ticks++;
    wakeup(&ticks);
    release(&tickslock);
    set_next_timeout();
}

int get_tick() {
  return ticks;
}

void
do_nothing(int interval)
{
  int last_tick = ticks;
  int count = 0;
  while(count < interval){
    printf("");
    int cur_tick = ticks;
    if (cur_tick != last_tick){
      last_tick = cur_tick;
      count++;
    }
  }
}

