template <typename T>
T ParseEnvOrDefault(const char* type_name, const char* env_name, boost::optional<T> user_value, float dflt) {
  return ParseEnvOrDefaultImpl<T>::ParseEnvOrDefault(type_name, env_name, user_value, dflt);
