{
    for(i=1;i<=6;i++) //1 2 3 4 5 6
    {
        pthread_mutex_lock(&mutex);/*锁住互斥量*/
		printf("thread1: lock  i = %d\n",  i  );
        if(i%3==0){
			printf("thread1:signal 1  i = %d\n",  i );
            pthread_cond_signal(&cond);/* 条件改变，发送信号，通知t_b进程 */
