 * Module entry points.
 */
int
_init(void)
{
	int error;

	neti_init();
	error = mod_install(&modlinkage);
	if (error != 0)
		neti_fini();

	return (error);
}


int
_fini(void)
{
	int error;

	error = mod_remove(&modlinkage);
	if (error == 0)
		neti_fini();

	return (error);
}


int
_info(struct modinfo *modinfop)
{

	return (mod_info(&modlinkage, modinfop));
}

