#include <stdio.h>
#include <rpc/rpc.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include <errno.h>
#include <stdio.h>
#include <assert.h>
#include "svc_stats.h"

#ifdef PURIFY
#include <purify.h>
#endif

#define rpc_buffer(xprt) ((xprt)->xp_p1)
#ifndef MAX
#define MAX(a, b)     ((a > b) ? a : b)
#endif

static bool_t		svcudp_recv();
static bool_t		svcudp_reply();
static enum xprt_stat	svcudp_stat();
static bool_t		svcudp_getargs();
static bool_t		svcudp_freeargs();
static void			svcudp_destroy();
static void			svcudp_disablecache();

static struct xp_ops svcudp_op = {
	svcudp_recv,
	svcudp_stat,
	svcudp_getargs,
	svcudp_reply,
	svcudp_freeargs,
	svcudp_destroy
};

extern int errno;
#ifdef DEBUG
static int debug=0;
static int debug1=0;
static int debugm=0;
#endif

/*
 * kept in xprt->xp_p2
 */
struct svcudp_data {
	u_int   su_iosz;	/* byte size of send.recv buffer */
	u_long	su_xid;		/* transaction id */
	XDR	su_xdrs;	/* XDR handle */
	char	su_verfbody[MAX_AUTH_BYTES];	/* verifier body */
	char * 	su_cache;	/* cached data, NULL if no cache */
};
#define	su_data(xprt)	((struct svcudp_data *)(xprt->xp_p2))

#include "svc_udp_cache.h"

/*
 * Usage:
 *	xprt = svcudp_create(sock);
 *
 * If sock<0 then a socket is created, else sock is used.
 * If the socket, sock is not bound to a port then svcudp_create
 * binds it to an arbitrary port.  In any (successful) case,
 * xprt->xp_sock is the registered socket number and xprt->xp_port is the
 * associated port number.
 * Once *xprt is initialized, it is registered as a transporter;
 * see (svc.h, xprt_register).
 * The routines returns NULL if a problem occurred.
 */
SVCXPRT *
svcudp_bufcreate(sock, sendsz, recvsz)
	register int sock;
	u_int sendsz, recvsz;
{
	bool_t madesock = FALSE;
	register SVCXPRT *xprt;
	register struct svcudp_data *su;
	struct sockaddr_in addr;
	int len = sizeof(struct sockaddr_in);

#ifdef DEBUG
	if(debugm) {
		fprintf(stderr, "svcudp_bufcreate sock=%d %d\n",sock, __LINE__);
	}
#endif

	if (sock == RPC_ANYSOCK) {
		if ((sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)) < 0) {
			perror("svcudp_create: socket creation problem");
			return ((SVCXPRT *)NULL);
		}
		madesock = TRUE;
	}
	bzero((char *)&addr, sizeof (addr));
	addr.sin_family = AF_INET;
	if (bindresvport(sock, &addr)) {
		addr.sin_port = 0;
		(void)bind(sock, (struct sockaddr *)&addr, len);
	}
	if (getsockname(sock, (struct sockaddr *)&addr, &len) != 0) {
		perror("svcudp_create - cannot getsockname");
		if (madesock)
			(void)close(sock);
		return ((SVCXPRT *)NULL);
	}
	xprt = (SVCXPRT *)mem_alloc(sizeof(SVCXPRT));
	if (xprt == NULL) {
		(void)fprintf(stderr, "svcudp_create: out of memory\n");
		return (NULL);
	}
	su = (struct svcudp_data *)mem_alloc(sizeof(*su));
	if (su == NULL) {
		(void)fprintf(stderr, "svcudp_create: out of memory\n");
		return (NULL);
	}
	su->su_xid = 0; /* else umr */
	su->su_iosz = ((MAX(sendsz, recvsz) + 3) / 4) * 4;
	if ((rpc_buffer(xprt) = (caddr_t) mem_alloc(su->su_iosz)) == NULL) {
		(void)fprintf(stderr, "svcudp_create: out of memory\n");
		assert(0);
		return (NULL);
	}
	xdrmem_create(
	    &(su->su_xdrs), rpc_buffer(xprt), su->su_iosz, XDR_DECODE);
	su->su_cache = NULL;
	xprt->xp_p2 = (caddr_t)su;
	xprt->xp_verf.oa_base = su->su_verfbody;
	xprt->xp_ops = &svcudp_op;
	xprt->xp_port = ntohs(addr.sin_port);
	xprt->xp_sock = sock;
	xprt_register(xprt);
	return (xprt);
}

SVCXPRT *
svcudp_create(sock)
	int sock;
{

	return(svcudp_bufcreate(sock, UDPMSGSIZE, UDPMSGSIZE));
}

static enum xprt_stat
svcudp_stat(xprt)
	SVCXPRT *xprt;
{

	return (XPRT_IDLE); 
}



#ifdef DEBUG
extern void memdump();
#endif

static bool_t
svcudp_recv(xprt, msg)
	register SVCXPRT *xprt;
	struct rpc_msg *msg;
{
	register struct svcudp_data *su = su_data(xprt);
	register XDR *xdrs = &(su->su_xdrs);
	register int rlen;
	char *reply;
	u_long replylen;
	int 	is_retrans =0;


#ifdef DEBUG
	if(debug) {
		fprintf(stderr, "svcudp_recv %d\n" , __LINE__);
	}
#endif

    again:
	xprt->xp_addrlen = sizeof(struct sockaddr_in);

	assert(rpc_buffer(xprt) != 0);

#ifdef DEBUG
	if(debug) {
	fprintf(stderr, 
		"svcudp_recv called recvfrom(%d,0x%x, %d,%d,0x%x,0x%x)\n",
		xprt->xp_sock, rpc_buffer(xprt), (int) su->su_iosz,
	    0, (struct sockaddr *)&(xprt->xp_raddr), &(xprt->xp_addrlen));
	}
#endif
#ifdef PURIFY
	/*
	// purify doesn't seem to recognize
	// read() system call as an initializer
	*/
	if(purify_is_running()) {
		bzero(rpc_buffer(xprt), (int)su->su_iosz);
	}
#endif
	svc_stats()->udp.recvfroms++;

	rlen = recvfrom(xprt->xp_sock, rpc_buffer(xprt), (int) su->su_iosz,
	    0, (struct sockaddr *)&(xprt->xp_raddr), &(xprt->xp_addrlen));

	{	/* keep track of largest request */ 	
		if (svc_stats()->udp.reqmax < rlen) 
			svc_stats()->udp.reqmax = rlen;
	}

#ifdef DEBUG
	if(debug) {
		fprintf(stderr, "recvfrom got rlen %d at %d\n",
			rlen,__LINE__);
		memdump(rpc_buffer(xprt), rlen, "UDP-READ");
	}
#endif

	if (rlen == -1 && errno == EINTR) {
#ifdef DEBUG
	if(debug) {
		fprintf(stderr, "EINTR svcudp_recv %d\n" , __LINE__);
	}
#endif
		goto again;
	}
	if (rlen == -1 == EINTR) {
		perror("recvfrom");
		exit(1);
	}
	if (rlen < 4*sizeof(u_long)){
#ifdef DEBUG
	if(debug) {
		fprintf(stderr, "svcudp_recv returned DROP rlen %d at %d\n",
			rlen,__LINE__);
	}
#endif
		return (FALSE);
	}
	xdrs->x_op = XDR_DECODE;
	XDR_SETPOS(xdrs, 0);
	if (! xdr_callmsg(xdrs, msg)) {

#ifdef DEBUG
	if(debug) {
		fprintf(stderr, "svcudp_recv returned DROP at %d\n" , __LINE__);
	}
#endif
		return (FALSE);
	}

	xprt->xp_xid = su->su_xid = msg->rm_xid;
	if (su->su_cache != NULL) {
		switch (cache_get(xprt, msg, &reply, &replylen)) {
		case SENDREPLY:
			svc_stats()->udp.rereplies++;
			/* retrans with cached reply */

#ifdef DEBUG
	if(debug) {
			fprintf(stderr, "cached (id=%d); sendto(%d,,%d,0,%s)\n",
				msg->rm_xid,
				xprt->xp_sock, replylen,
				inet_ntoa(
				((struct sockaddr_in *)(&xprt->xp_raddr))->sin_addr));
	}
#endif

			{	/* keep track of largest reply */ 	
				if (svc_stats()->udp.replymax < replylen) 
					svc_stats()->udp.replymax = replylen;
			}

			(void) sendto(xprt->xp_sock, reply, (int) replylen, 0,
			  (struct sockaddr *) &xprt->xp_raddr, xprt->xp_addrlen);
#			ifdef DEBUG
			if(debug) {
				fprintf(stderr, "svcudp_recv returned DROP at %d\n" , __LINE__);
			}
#			endif
			return FALSE;

		case DROPIT:
			svc_stats()->udp.drops++;
#			ifdef DEBUG
			if(debug) {
				fprintf(stderr, "svcudp_recv returned DROP at %d\n" , __LINE__);
			}
#			endif
			return FALSE;

		case DOIT:
			svc_stats()->udp.done++;
#			ifdef DEBUG
			if(debug) {
				fprintf(stderr, "svcudp_recv returned DONE at %d\n" , __LINE__);
			}
#			endif
			return TRUE;
		}
	}
#ifdef DEBUG
	if(debug) {
	fprintf(stderr, "svcudp_recv returned DONE at %d\n" , __LINE__);
	}
#endif

	/* same as DOIT */
	return (TRUE);
}

static bool_t
svcudp_reply(xprt, msg)
	register SVCXPRT *xprt; 
	struct rpc_msg *msg; 
{
	register struct svcudp_data *su = su_data(xprt);
	register XDR *xdrs = &(su->su_xdrs);
	register int slen;
	register bool_t stat = FALSE;

	xdrs->x_op = XDR_ENCODE;
	XDR_SETPOS(xdrs, 0);
	msg->rm_xid = su->su_xid;
	if (xdr_replymsg(xdrs, msg)) {
		slen = (int)XDR_GETPOS(xdrs);
		svc_stats()->udp.replies++;

		if (sendto(xprt->xp_sock, rpc_buffer(xprt), slen, 0,
		    (struct sockaddr *)&(xprt->xp_raddr), xprt->xp_addrlen)
		    == slen) {
			stat = TRUE;
			if (su->su_cache && slen >= 0) {
				cache_set(xprt, msg, (u_long) slen);
			}
		}
	}
	return (stat);
}

static bool_t
svcudp_getargs(xprt, xdr_args, args_ptr)
	SVCXPRT *xprt;
	xdrproc_t xdr_args;
	caddr_t args_ptr;
{

	return ((*xdr_args)(&(su_data(xprt)->su_xdrs), args_ptr));
}

static bool_t
svcudp_freeargs(xprt, xdr_args, args_ptr)
	SVCXPRT *xprt;
	xdrproc_t xdr_args;
	caddr_t args_ptr;
{
	register XDR *xdrs = &(su_data(xprt)->su_xdrs);

	xdrs->x_op = XDR_FREE;
	return ((*xdr_args)(xdrs, args_ptr));
}

static void
svcudp_destroy(xprt)
	register SVCXPRT *xprt;
{
	register struct svcudp_data *su = su_data(xprt);
#ifdef DEBUG
	if(debugm) {
		fprintf(stderr, "svcudp_destroy %d\n" , __LINE__);
	}
#endif

	xprt_unregister(xprt);
	(void)close(xprt->xp_sock);
	XDR_DESTROY(&(su->su_xdrs));
	mem_free(rpc_buffer(xprt), su->su_iosz);

#ifdef DEBUG
	if(debugm) {
		fprintf(stderr, "svcudp_destroy %d\n" , __LINE__);
	}
#endif
	if (su->su_cache != NULL) {
		svcudp_disablecache(&(su->su_cache));
	}
#ifdef DEBUG
	if(debugm) {
		fprintf(stderr, "svcudp_destroy %d\n" , __LINE__);
	}
#endif
	mem_free((caddr_t)su, sizeof(struct svcudp_data));
	mem_free((caddr_t)xprt, sizeof(SVCXPRT));
}


