ac_err_t
ac_kpm_err_cvt(int err)
{
	switch (err) {
	case KPHYSM_ESPAN:
		return (AC_ERR_KPM_SPAN);
	case KPHYSM_EFAULT:
		return (AC_ERR_KPM_FAULT);
	case KPHYSM_ERESOURCE:
