void display(void) 
{
    glClearColor(0.95f, 0.95f, 0.95f, 1.0f);
    glClear(GL_COLOR_BUFFER_BIT); 

    glColor3f(1.0f, 0.25, 0.25f);
    glBegin(GL_POLYGON);
	glVertex2f(-2.0, 2.0);
	glVertex2f(2.0, 2.0);
        // polygon is basically triangle fan ...
        if( convex )
	    glVertex2f(3.0, 0.0);
        else
	    glVertex2f(0.0, 3.0);
	glVertex2f(2.0, -2.0);
	glVertex2f(-2.0, -2.0);
    glEnd();

    glFlush();
}

void key(unsigned char k,int x,int y)
{
    convex = !convex;
    glutPostRedisplay();
}

